// Dense Jonker-Volgenant / shortest-augmenting-path assignment solver.
// Minimizes sum_i cost[i, col[i]].
// Algorithm follows the classical O(n^3) LAPJV / Hungarian dual formulation:
// reduced cost c'(i,j) = c(i,j) - u[i] - v[j] >= 0, edges with c'=0 are admissible.
#include <algorithm>
#include <cmath>
#include <cstdint>
#include <cstring>
#include <limits>
#include <vector>
#include <cstdio>

void lapjv(int n, const double* cost, int* col_of_row) {
    const double INF = std::numeric_limits<double>::infinity();
    std::vector<double> u(n), v(n, 0.0);
    std::vector<int> row_of_col(n, -1);
    std::vector<double> dist(n);
    std::vector<int> pred(n);
    std::vector<int> scanned(n); // 0/1

    // Column reduction initialization (helps a bit): assign each column to its min row if free
    // We'll just start with u[i] = min_j cost[i,j] which makes reduced costs nonnegative.
    for (int i = 0; i < n; ++i) {
        double m = INF;
        const double* row = cost + static_cast<long>(i) * n;
        for (int j = 0; j < n; ++j) m = std::min(m, row[j]);
        u[i] = m;
    }

    for (int i = 0; i < n; ++i) {
        // shortest path from free row i
        std::fill(dist.begin(), dist.end(), INF);
        std::fill(pred.begin(), pred.end(), -1);
        std::fill(scanned.begin(), scanned.end(), 0);

        int jmin = -1;
        // seed distances from row i
        {
            const double* row = cost + static_cast<long>(i) * n;
            double ui = u[i];
            for (int j = 0; j < n; ++j) {
                dist[j] = row[j] - ui - v[j];
                pred[j] = i;
            }
        }

        int free_col = -1;
        while (true) {
            // pick closest unscanned column
            double dmin = INF;
            jmin = -1;
            for (int j = 0; j < n; ++j) {
                if (!scanned[j] && dist[j] < dmin) {
                    dmin = dist[j];
                    jmin = j;
                }
            }
            scanned[jmin] = 1;

            // dual update can be deferred; we track path lengths in dist which already
            // include the shortest-path distance from the free row in the residual graph
            // with reduced costs.
            int r = row_of_col[jmin];
            if (r < 0) {
                free_col = jmin;
                break;
            }
            // relax edges out of row r (which is matched to jmin)
            // The residual allows leaving the matched column jmin into row r, then to any column j.
            // Length of going through this matched edge:
            // The reduced cost of the matched edge (r, jmin) is 0 (maintained invariant).
            // New candidate distance to column j:
            //   dist[jmin] + (cost[r,j] - u[r] - v[j]) - (cost[r,jmin] - u[r] - v[jmin])
            // = dist[jmin] + cost[r,j] - v[j] - cost[r,jmin] + v[jmin]
            // Since reduced cost of matched edge is 0:
            //   cost[r,jmin] - u[r] - v[jmin] == 0 => cost[r,jmin] - v[jmin] == u[r]
            // so candidate = dist[jmin] + cost[r,j] - u[r] - v[j]
            const double* row = cost + static_cast<long>(r) * n;
            double base = dist[jmin] - u[r];
            for (int j = 0; j < n; ++j) {
                if (scanned[j]) continue;
                double cand = base + row[j] - v[j];
                if (cand < dist[j]) {
                    dist[j] = cand;
                    pred[j] = r;
                }
            }
        }

        // Dual updates:
        // For every scanned column j, v[j] += dist[j] - dmin_final? 
        // Standard update after shortest path of length delta = dist[free_col]:
        //   u[row] += delta - dist[matched_col_of_row]   for rows on the path / scanned
        //   v[j]   -= delta - dist[j]                    for scanned columns
        // More precisely, with our dist definition (shortest path length to each column):
        // Let delta = dist[free_col].
        // For scanned columns: v[j] += dist[j] - delta   ? Let's derive.
        //
        // We want reduced costs to stay nonnegative and the path edges to become zero.
        // A well-known correct update (Burkard / Jonker-Volgenant):
        //   for all scanned columns j: v[j] = v[j] - dist[j] + delta? 
        // I'll use the formulation from the Hungarian method:
        //   theta = dist[free_col]
        //   for scanned j: v[j] += dist[j] - theta     NO.
        //
        // Let me recall the invariant: dist[j] is the shortest path length using reduced costs.
        // After augmentation we set:
        //   v[j] := v[j] + dist[j] - delta    for scanned j? 
        // Let's test empirically and also maintain u so matched reduced costs are 0.
        //
        // From Wikipedia / standard:
        // When a column j is permanently labeled with dual slack pi[j] (=dist[j]),
        // at the end:
        //   for every labeled column j: v_j := v_j + pi_j - delta? 
        //
        // I'll implement the update used by scipy's rectangular LSAP which is known correct,
        // but first let's try this common version and verify:
        //
        //   delta = dist[free_col]
        //   for j scanned: v[j] -= (delta - dist[j])     i.e. v[j] += dist[j] - delta
        //   for rows that are pred of a scanned column (i.e. rows from which we relaxed, plus start):
        //     u[r] += (delta - dist[matched_col]) 
        //
        // Matched column of row r (for r != start) is the column through which we entered r,
        // which is the column j where row_of_col[j] == r, and dist of that column is known.
        // For the starting row, matched column doesn't exist yet; u[i] += delta - 0.
        //
        double delta = dist[free_col];
        // update v for scanned columns
        for (int j = 0; j < n; ++j) {
            if (scanned[j]) {
                v[j] += dist[j] - delta;
            }
        }
        // update u for rows that appear as pred of a scanned column
        // The start row i has "dist_row" = 0.
        // Every scanned column j was reached from pred[j].
        // u[pred[j]] should be increased by (delta - dist_of_the_column_that_matches_pred) ...
        // Easier: for each scanned column j, the row pred[j] gets
        //   u[pred[j]] += delta - dist_at_entry
        // where dist_at_entry is 0 for start row, and dist[matched_col] for others.
        // Since each such row is pred of exactly the columns it relaxed to, we'd double-count.
        // So collect unique rows.
        //
        // Unique rows involved: start row, and row_of_col[j] for every scanned j except free_col.
        u[i] += delta; // entry distance 0
        for (int j = 0; j < n; ++j) {
            if (!scanned[j]) continue;
            int r = row_of_col[j];
            if (r >= 0) {
                // this row was entered via column j at distance dist[j]
                // and left toward other columns. Its potential increases by delta - dist[j].
                u[r] += delta - dist[j];
            }
        }

        // Augment along pred path
        int j = free_col;
        while (j >= 0) {
            int r = pred[j];
            int prev_j = -1;
            // find column previously matched to r (to continue the path)
            // For start row there is none.
            // We stored pred[j] = row that reaches j. The previous column is the one matched to that row
            // BEFORE augmentation, except we need it before we overwrite.
            // Search: previous column is the column currently assigned to r.
            for (int jj = 0; jj < n; ++jj) {
                if (row_of_col[jj] == r) { prev_j = jj; break; }
            }
            row_of_col[j] = r;
            if (r == i) break;
            j = prev_j;
        }
    }

    for (int j = 0; j < n; ++j) {
        int r = row_of_col[j];
        if (r >= 0) col_of_row[r] = j;
    }
}

int main() {
    // tiny test
    double M[4] = {0, 1, 1, 0};
    int col[2];
    lapjv(2, M, col);
    printf("%d %d\n", col[0], col[1]);
    return 0;
}
