// Sparse auction algorithm for the assignment problem on a k-NN bipartite graph,
// with a large penalty for missing edges so a perfect matching always exists.
// Prices updated in the Bertsekas epsilon-scaling auction.
#include <algorithm>
#include <cmath>
#include <cstdint>
#include <vector>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <chrono>
#include <random>
#include <queue>

struct Edge {
    int j;
    double c;
};

// Returns column assignment. kNN lists given as knn_j[i*k + t], knn_c similarly.
// n columns. Missing edges have cost = big.
void auction(int n, int k, const int* knn_j, const double* knn_c,
             double big, int* col_of_row, double eps_target) {
    // We'll run epsilon-scaling auction.
    // For each row, candidate costs are the k neighbors plus a "dummy" handled by
    // allowing assignment to any column at cost `big` — too expensive to enumerate.
    // Instead, unlisted columns all have the same cost `big`, so the best unlisted
    // column is simply the one with the smallest price (among those not in the kNN).
    // Maintaining the global min-price column is doable but prices change.
    // Simpler approach: build a full candidate only if needed.
    //
    // Practical approach used here:
    // Each person bids on their k neighbors only, BUT we also keep a virtual
    // "overflow" option: if the best neighbor benefit is worse than -price_min_global + (-big)? 
    // Let's just include all columns by using a heap of column prices to find the
    // cheapest unlisted column in O(log n).
    //
    // Column price heap: we need decrease/increase of arbitrary columns. Use lazy heap.

    std::vector<double> price(n, 0.0);
    std::vector<int> owner(n, -1);          // row assigned to column
    std::vector<int> assign(n, -1);         // column assigned to row
    std::vector<double> benefit(k + 1);

    // epsilon scaling
    double eps = 1.0; // start
    // estimate cost scale
    double cmax = 0;
    for (int i = 0; i < n * k; ++i) cmax = std::max(cmax, knn_c[i]);
    eps = cmax / 2.0 + 1e-6;

    auto run_phase = [&](double eps) {
        // reset assignment? For epsilon scaling, keep prices, reset assignment.
        std::fill(owner.begin(), owner.end(), -1);
        std::fill(assign.begin(), assign.end(), -1);
        int unassigned = n;
        std::vector<int> free_rows(n);
        for (int i = 0; i < n; ++i) free_rows[i] = i;
        int ftop = n;

        // lazy heap of (price, column, version)
        std::vector<int> ver(n, 0);
        using Item = std::pair<double, int>;
        std::priority_queue<Item, std::vector<Item>, std::greater<Item>> heap;
        for (int j = 0; j < n; ++j) heap.push({0.0, j});

        auto cheapest_unlisted = [&](const int* neigh, int kk, int& j_out) -> double {
            // pop until we find a column not in neigh with current price
            // To test membership, mark neigh in a stamp array — caller provides stamp.
            return 0;
        };

        std::vector<int> stamp(n, 0);
        int stamp_id = 1;

        int guard = 0;
        const int GUARD_MAX = n * 200;
        while (ftop > 0 && guard++ < GUARD_MAX) {
            int i = free_rows[--ftop];
            const int* nj = knn_j + static_cast<long>(i) * k;
            const double* nc = knn_c + static_cast<long>(i) * k;

            if (++stamp_id == 0) { std::fill(stamp.begin(), stamp.end(), 0); stamp_id = 1; }
            for (int t = 0; t < k; ++t) stamp[nj[t]] = stamp_id;

            // find best and second best among kNN and the best unlisted (cost big)
            // best unlisted: smallest price among columns not in kNN
            double best_unlisted_price = 1e300;
            int best_unlisted_j = -1;
            // scan heap lazily
            std::vector<Item> popped;
            while (!heap.empty()) {
                auto [p, j] = heap.top();
                if (p != price[j]) { heap.pop(); continue; } // stale
                if (stamp[j] == stamp_id) {
                    // listed, skip but keep
                    heap.pop();
                    popped.push_back({p, j});
                    continue;
                }
                best_unlisted_price = p;
                best_unlisted_j = j;
                break;
            }
            for (auto& it : popped) heap.push(it);

            // benefits: -cost - price  (we maximize -cost - price, i.e. minimize cost+price)
            // value of assigning j is -(cost + price)
            int best_j = -1, second_j = -1;
            double best_val = -1e300, second_val = -1e300;

            auto consider = [&](int j, double c) {
                double val = -(c + price[j]);
                if (val > best_val) {
                    second_val = best_val; second_j = best_j;
                    best_val = val; best_j = j;
                } else if (val > second_val) {
                    second_val = val; second_j = j;
                }
            };
            for (int t = 0; t < k; ++t) consider(nj[t], nc[t]);
            if (best_unlisted_j >= 0) consider(best_unlisted_j, big);

            // bid increment: best_val - second_val + eps
            double bid_inc = best_val - second_val + eps;
            // new price of best_j: price increases so that its value equals second_val - eps
            // val = -(c + price) ; we want new_val = second_val - eps
            // -(c + new_price) = second_val - eps
            // new_price = -c - second_val + eps? wait
            // best_val = -(c + old_price)
            // new_price = old_price + (best_val - second_val) + eps
            double new_price = price[best_j] + bid_inc;
            price[best_j] = new_price;
            ver[best_j]++;
            heap.push({new_price, best_j});

            int prev = owner[best_j];
            owner[best_j] = i;
            assign[i] = best_j;
            if (prev >= 0) {
                assign[prev] = -1;
                free_rows[ftop++] = prev;
            } else {
                // assigned a previously free column; unassigned count drops implicitly via ftop
            }
        }
        if (ftop > 0) {
            // did not finish
            return false;
        }
        return true;
    };

    // scaling loop
    int phases = 0;
    while (true) {
        bool ok = run_phase(eps);
        phases++;
        if (!ok) {
            printf("phase failed eps=%g\n", eps);
            break;
        }
        if (eps <= eps_target) break;
        eps = std::max(eps_target, eps / 5.0);
    }
    for (int i = 0; i < n; ++i) col_of_row[i] = assign[i];
    // fprintf(stderr, "phases %d final eps %g\n", phases, eps);
}

int main() {
    int n = 600;
    int k = 32;
    std::mt19937 rng(0);
    std::uniform_real_distribution<double> ud(0.0, 1.0);
    std::vector<double> sp(n*2), tp(n*2);
    for (int i = 0; i < n*2; ++i) { sp[i]=ud(rng); tp[i]=ud(rng); }
    // compute full cost and knn
    std::vector<double> cost(static_cast<long>(n)*n);
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j) {
            double dx=sp[2*i]-tp[2*j], dy=sp[2*i+1]-tp[2*j+1];
            cost[(long)i*n+j] = std::sqrt(dx*dx+dy*dy);
        }
    std::vector<int> knn_j(n*k);
    std::vector<double> knn_c(n*k);
    std::vector<int> idx(n);
    for (int i = 0; i < n; ++i) {
        std::iota(idx.begin(), idx.end(), 0);
        std::partial_sort(idx.begin(), idx.begin()+k, idx.end(), [&](int a, int b){
            return cost[(long)i*n+a] < cost[(long)i*n+b];
        });
        for (int t = 0; t < k; ++t) {
            knn_j[(long)i*k+t] = idx[t];
            knn_c[(long)i*k+t] = cost[(long)i*n+idx[t]];
        }
    }
    double big = 10.0; // larger than any distance (max dist < sqrt(2))
    std::vector<int> col(n);
    auto t0 = std::chrono::high_resolution_clock::now();
    auction(n, k, knn_j.data(), knn_c.data(), big, col.data(), 1e-8);
    auto t1 = std::chrono::high_resolution_clock::now();
    double ms = std::chrono::duration<double, std::milli>(t1-t0).count();
    double s = 0; int bad=0;
    std::vector<char> used(n,0);
    for (int i = 0; i < n; ++i) {
        if (col[i] < 0 || col[i] >= n || used[col[i]]) { bad++; continue; }
        used[col[i]]=1;
        s += cost[(long)i*n+col[i]];
    }
    printf("auction n=%d k=%d time=%.3f ms cost=%g invalid=%d\n", n, k, ms, s, bad);
    return 0;
}
