#include <algorithm>
#include <cmath>
#include <cstdint>
#include <vector>
#include <cstdio>
#include <cstdlib>
#include <numeric>
#include <random>
#include <chrono>
#include <cstring>

// Sparse epsilon-scaling auction.
// Candidates per row: k nearest columns, plus one virtual "outside" column
// representing the cheapest column not in the kNN (cost = big).
// big must exceed every real edge cost so an optimal matching that lies
// inside the kNN never uses an outside edge. If the final matching uses an
// outside edge, the caller should increase k.

struct CSR {
    int n, k;
    std::vector<int> j;      // n*k
    std::vector<double> c;   // n*k
};

void auction_sparse(const CSR& g, double big, double eps_target, int* assign, int* outside_count) {
    int n = g.n, k = g.k;
    std::vector<double> price(n, 0.0);
    std::vector<int> owner(n, -1);

    double cmax = 0;
    for (double x : g.c) cmax = std::max(cmax, x);
    double eps = std::max(cmax, big) / 2.0 + 1e-12;

    std::vector<int> stamp(n, 0);
    int stamp_id = 1;
    // lazy min-heap of column prices: pair stored as index into arrays to avoid alloc
    // We'll use a binary heap of column indices keyed by price, with version stamps.
    std::vector<int> heap_pos(n, -1);
    std::vector<int> heap;
    heap.reserve(n);

    auto sift_up = [&](int p) {
        int j = heap[p];
        while (p > 0) {
            int par = (p - 1) / 2;
            int pj = heap[par];
            if (price[pj] <= price[j]) break;
            heap[p] = pj; heap_pos[pj] = p;
            p = par;
        }
        heap[p] = j; heap_pos[j] = p;
    };
    auto sift_down = [&](int p) {
        int j = heap[p];
        int sz = (int)heap.size();
        while (true) {
            int l = 2 * p + 1, r = l + 1, best = p;
            if (l < sz && price[heap[l]] < price[heap[best]]) best = l;
            if (r < sz && price[heap[r]] < price[heap[best]]) best = r;
            if (best == p) break;
            int bj = heap[best];
            heap[best] = j; // temporary, fix below
            heap[p] = bj; heap_pos[bj] = p;
            p = best;
            j = heap[p]; // wrong — let me rewrite more carefully
        }
    };

    // Rewrite heap ops more carefully with a simple class-like redo below.
    // (The sift_down above is buggy; we won't use these lambdas.)
    (void)sift_up; (void)sift_down; (void)heap_pos; (void)heap;

    // Use std::priority_queue style lazy invalidation instead — simpler and fast enough.
    // Implemented inside the phase loop.

    int phases = 0;
    while (true) {
        std::fill(owner.begin(), owner.end(), -1);
        std::fill(assign, assign + n, -1);
        std::vector<int> free_rows(n);
        std::iota(free_rows.begin(), free_rows.end(), 0);
        int ftop = n;

        // lazy heap: (price, column). Stale if price doesn't match.
        // Use a binary heap manually to avoid pair allocations.
        struct Node { double p; int j; };
        std::vector<Node> H;
        H.reserve(n);
        auto push = [&](double p, int j) {
            H.push_back({p, j});
            int i = (int)H.size() - 1;
            while (i > 0) {
                int par = (i - 1) / 2;
                if (H[par].p <= H[i].p) break;
                std::swap(H[par], H[i]);
                i = par;
            }
        };
        auto pop_valid = [&](int& j_out, double& p_out, auto& skip) -> bool {
            while (!H.empty()) {
                Node nd = H[0];
                // pop
                H[0] = H.back(); H.pop_back();
                int i = 0;
                int sz = (int)H.size();
                while (true) {
                    int l = 2 * i + 1, r = l + 1, b = i;
                    if (l < sz && H[l].p < H[b].p) b = l;
                    if (r < sz && H[r].p < H[b].p) b = r;
                    if (b == i) break;
                    std::swap(H[i], H[b]);
                    i = b;
                }
                if (nd.p != price[nd.j]) continue; // stale
                if (skip(nd.j)) {
                    // not eligible; remember to push back after? We must not lose it.
                    // Push it into a side buffer.
                    return false; // signal caller differently — redesign
                }
                j_out = nd.j; p_out = nd.p;
                return true;
            }
            return false;
        };
        (void)pop_valid;

        for (int j = 0; j < n; ++j) push(price[j], j);

        std::vector<Node> skipped;
        skipped.reserve(k);

        int guard = 0;
        const int GUARD_MAX = n * 400;
        bool failed = false;
        while (ftop > 0) {
            if (++guard > GUARD_MAX) { failed = true; break; }
            int i = free_rows[--ftop];
            const int* nj = g.j.data() + (long)i * k;
            const double* nc = g.c.data() + (long)i * k;

            if (++stamp_id == 0) { std::fill(stamp.begin(), stamp.end(), 0); stamp_id = 1; }
            for (int t = 0; t < k; ++t) stamp[nj[t]] = stamp_id;

            // extract cheapest unlisted column
            skipped.clear();
            int un_j = -1;
            double un_p = 0;
            while (!H.empty()) {
                Node nd = H[0];
                // pop
                H[0] = H.back(); H.pop_back();
                int ii = 0, sz = (int)H.size();
                while (true) {
                    int l = 2 * ii + 1, r = l + 1, b = ii;
                    if (l < sz && H[l].p < H[b].p) b = l;
                    if (r < sz && H[r].p < H[b].p) b = r;
                    if (b == ii) break;
                    std::swap(H[ii], H[b]);
                    ii = b;
                }
                if (nd.p != price[nd.j]) continue;
                if (stamp[nd.j] == stamp_id) {
                    skipped.push_back(nd);
                    continue;
                }
                un_j = nd.j; un_p = nd.p;
                break;
            }
            // restore skipped and the chosen unlisted (still in heap, price unchanged yet)
            for (auto& nd : skipped) push(nd.p, nd.j);
            if (un_j >= 0) push(un_p, un_j);

            int best_j = -1;
            double best_val = -1e300, second_val = -1e300;
            auto consider = [&](int j, double c) {
                double val = -(c + price[j]);
                if (val > best_val) {
                    second_val = best_val;
                    best_val = val;
                    best_j = j;
                } else if (val > second_val) {
                    second_val = val;
                }
            };
            for (int t = 0; t < k; ++t) consider(nj[t], nc[t]);
            if (un_j >= 0) consider(un_j, big);

            double bid_inc = best_val - second_val + eps;
            if (bid_inc < eps) bid_inc = eps; // numerical guard
            price[best_j] += bid_inc;
            push(price[best_j], best_j);

            int prev = owner[best_j];
            owner[best_j] = i;
            assign[i] = best_j;
            if (prev >= 0) free_rows[ftop++] = prev;
        }
        phases++;
        if (failed) {
            printf("FAILED phase %d eps %g ftop %d\n", phases, eps, ftop);
            *outside_count = -1;
            return;
        }
        if (eps <= eps_target) break;
        eps *= 0.25;
        if (eps < eps_target) eps = eps_target;
        if (phases > 60) break;
    }
    // count outside
    int out = 0;
    for (int i = 0; i < n; ++i) {
        const int* nj = g.j.data() + (long)i * k;
        int j = assign[i];
        bool in = false;
        for (int t = 0; t < k; ++t) if (nj[t] == j) { in = true; break; }
        if (!in) out++;
    }
    *outside_count = out;
    fprintf(stderr, "phases %d\n", phases);
}

int main(int argc, char** argv) {
    int n = argc > 1 ? atoi(argv[1]) : 600;
    int k = argc > 2 ? atoi(argv[2]) : 40;
    int seed = argc > 3 ? atoi(argv[3]) : 0;
    std::mt19937 rng(seed);
    std::uniform_real_distribution<double> ud(0.0, 1.0);
    std::vector<double> sp(n * 2), tp(n * 2);
    for (int i = 0; i < n * 2; ++i) { sp[i] = ud(rng); tp[i] = ud(rng); }

    auto t0 = std::chrono::high_resolution_clock::now();
    // build cost + knn
    std::vector<double> cost((long)n * n);
    for (int i = 0; i < n; ++i) {
        double sx = sp[2 * i], sy = sp[2 * i + 1];
        double* row = cost.data() + (long)i * n;
        for (int j = 0; j < n; ++j) {
            double dx = sx - tp[2 * j], dy = sy - tp[2 * j + 1];
            row[j] = std::sqrt(dx * dx + dy * dy);
        }
    }
    CSR g; g.n = n; g.k = k; g.j.resize((long)n * k); g.c.resize((long)n * k);
    std::vector<int> idx(n);
    for (int i = 0; i < n; ++i) {
        std::iota(idx.begin(), idx.end(), 0);
        const double* row = cost.data() + (long)i * n;
        std::nth_element(idx.begin(), idx.begin() + k, idx.end(), [&](int a, int b) {
            return row[a] < row[b];
        });
        // not fully sorted; auction doesn't need sorted neighbors
        for (int t = 0; t < k; ++t) {
            g.j[(long)i * k + t] = idx[t];
            g.c[(long)i * k + t] = row[idx[t]];
        }
    }
    auto t1 = std::chrono::high_resolution_clock::now();
    std::vector<int> assign(n);
    int outside = 0;
    double big = 10.0;
    auction_sparse(g, big, 1e-8, assign.data(), &outside);
    auto t2 = std::chrono::high_resolution_clock::now();
    double s = 0; int bad = 0;
    std::vector<char> used(n, 0);
    for (int i = 0; i < n; ++i) {
        int j = assign[i];
        if (j < 0 || j >= n || used[j]) { bad++; continue; }
        used[j] = 1;
        s += cost[(long)i * n + j];
    }
    double ms_build = std::chrono::duration<double, std::milli>(t1 - t0).count();
    double ms_auc = std::chrono::duration<double, std::milli>(t2 - t1).count();
    printf("n=%d k=%d build=%.2f ms auction=%.2f ms cost=%g bad=%d outside=%d\n",
           n, k, ms_build, ms_auc, s, bad, outside);
    FILE* f = fopen("build/as.txt", "w");
    fprintf(f, "%d %d\n", n, seed);
    for (int i = 0; i < n; ++i) fprintf(f, "%d\n", assign[i]);
    fclose(f);
    return 0;
}
