// Sparse Jonker-Volgenant on a k-NN graph plus implicit "outside" edges of cost BIG.
// Outside edges all have the same cost, so the best unscanned outside column is the
// one with minimum (BIG - v[j]) = minimum -v[j], i.e. maximum v among columns not
// in the row's neighbor list and not yet scanned.
//
// For the shortest-path phase we still need distances to ALL columns because an
// outside edge might be used as a bridge. With k << n, the inner loop is:
//   for each of k neighbors: relax if better
//   plus one "best outside" candidate.
// But Dijkstra still scans up to n columns (the labeled set can be large).
// The per-augmentation cost becomes O(n * k + n log n) if we use a heap for column selection,
// or O(n^2) if we scan all columns for the min dist.
//
// Key optimization: most columns that are ONLY reachable via outside edges share a
// simple distance formula and we can handle them in bulk.
//
// Distance to an unlisted column j from the current tree:
//   dist[j] = min over scanned matched-rows r that do NOT list j of:
//        dist[matched_col(r)] + BIG - u[r] - v[j]
//   which is (BIG - v[j]) + min_{such r} (dist[mc(r)] - u[r])
// This is messy because "such r" depends on j.
//
// Simpler fast path: use a binary heap Dijkstra and only generate k explicit edges
// plus, when relaxing a row, also consider that the row can reach every non-neighbor
// at cost BIG. Represent that as: maintain a global "outside offer" from each scanned row:
//   offer_r = dist[mc(r)] - u[r] + BIG
//   dist[j] <= offer_r - v[j] for j not neighbor of r and not scanned.
// The best offer for a column j is min over scanned rows that don't list j of offer_r.
// If no scanned row lists j (typical!), best offer is simply the global min offer.
// Columns listed by the row that holds the global min offer need the second-min offer.
//
// Implementation plan for the min-finding scan:
// We still need the minimum dist among unscanned columns. For columns not yet
// explicitly relaxed by a neighbor edge, dist[j] = best_offer(j) - v[j].
// Computing that naively is O(n) per Dijkstra iteration = O(n^2) total, same as dense.
//
// So pure sparse JV with outside edges doesn't beat O(n^3) unless the number of
// scanned columns per augmentation is small (like O(k) or O(log n)).
// Let's MEASURE how many columns get scanned per augmentation on these geometric instances
// when we ONLY allow kNN edges (no outside). If the optimum is inside kNN, JV on the
// sparse graph scans few columns.
//
// This program implements sparse JV on kNN edges ONLY (no outside). It reports
// whether it found a perfect matching, the cost, and the number of column-scans.

#include <algorithm>
#include <chrono>
#include <cmath>
#include <cstdio>
#include <cstdlib>
#include <limits>
#include <numeric>
#include <random>
#include <vector>

struct Graph {
    int n, k;
    std::vector<int> j;
    std::vector<double> c;
};

bool sparse_jv(const Graph& g, const std::vector<double>& full_cost, int* col_of_row, long* scans) {
    int n = g.n, k = g.k;
    const double INF = 1e100;
    std::vector<double> u(n, 0.0), v(n, 0.0);
    std::vector<int> row_of_col(n, -1);
    std::vector<int> prev_col_of_row(n, -1);
    std::vector<double> dist(n);
    std::vector<int> pred(n);
    std::vector<char> scanned(n);
    std::vector<int> touched; touched.reserve(n);

    // init u[i] = min neighbor cost
    for (int i = 0; i < n; ++i) {
        double m = INF;
        const double* row = g.c.data() + (long)i * k;
        for (int t = 0; t < k; ++t) m = std::min(m, row[t]);
        u[i] = m;
    }

    *scans = 0;
    for (int i = 0; i < n; ++i) {
        // reset only touched from previous? full fill is ok and cheap vs the search
        std::fill(dist.begin(), dist.end(), INF);
        std::fill(scanned.begin(), scanned.end(), 0);

        {
            const int* nj = g.j.data() + (long)i * k;
            const double* nc = g.c.data() + (long)i * k;
            double ui = u[i];
            for (int t = 0; t < k; ++t) {
                int j = nj[t];
                double d = nc[t] - ui - v[j];
                if (d < dist[j]) {
                    dist[j] = d;
                    pred[j] = i;
                }
            }
        }

        int free_col = -1;
        int scanned_count = 0;
        while (true) {
            double dmin = INF;
            int jmin = -1;
            for (int j = 0; j < n; ++j) {
                if (!scanned[j] && dist[j] < dmin) {
                    dmin = dist[j];
                    jmin = j;
                }
            }
            if (jmin < 0 || dmin >= INF / 2) {
                // cannot reach a free column within the sparse graph
                return false;
            }
            scanned[jmin] = 1;
            ++scanned_count;
            ++(*scans);
            int r = row_of_col[jmin];
            if (r < 0) { free_col = jmin; break; }

            const int* nj = g.j.data() + (long)r * k;
            const double* nc = g.c.data() + (long)r * k;
            double base = dist[jmin] - u[r];
            for (int t = 0; t < k; ++t) {
                int j = nj[t];
                if (scanned[j]) continue;
                double cand = base + nc[t] - v[j];
                if (cand < dist[j]) {
                    dist[j] = cand;
                    pred[j] = r;
                }
            }
            // safety: if we've scanned everything, fail
            if (scanned_count > n) return false;
        }

        double delta = dist[free_col];
        for (int j = 0; j < n; ++j) if (scanned[j]) v[j] += dist[j] - delta;
        u[i] += delta;
        for (int j = 0; j < n; ++j) {
            if (!scanned[j]) continue;
            int r = row_of_col[j];
            if (r >= 0) u[r] += delta - dist[j];
        }

        int j = free_col;
        while (true) {
            int r = pred[j];
            int prev_j = prev_col_of_row[r];
            row_of_col[j] = r;
            prev_col_of_row[r] = j;
            if (r == i) break;
            j = prev_j;
        }
    }
    for (int j = 0; j < n; ++j) col_of_row[row_of_col[j]] = j;
    return true;
}

int main(int argc, char** argv) {
    int n = argc > 1 ? atoi(argv[1]) : 600;
    int k = argc > 2 ? atoi(argv[2]) : 80;
    int seed = argc > 3 ? atoi(argv[3]) : 0;
    std::mt19937 rng(seed);
