#include <cstdlib>
#include <numeric>
#include <random>
#include <vector>
#include <cstdint>

// Sparse shortest-augmenting-path assignment on a fixed k-NN graph.
// Returns false if the sparse graph has no perfect matching.
// On success, match_col[i] is the assigned column.
// Also returns duals u, v satisfying reduced-cost optimality ON THE SPARSE EDGES.
// A subsequent dense pricing check can verify global optimality:
//   min over all i,j of (cost[i,j] - u[i] - v[j]) >= -tol
// If violated, the violating columns can be added and the search restarted
// (not done here).

struct Result {
    bool ok;
    double ms;
    long relax_edges;
    long scan_cols;
};

Result sparse_jv(int n, int k, const int* nb, const double* nc,
                 int* match_col, double* u, double* v) {
    const double INF = 1e100;
    std::vector<int> row_of_col(n, -1);
    std::vector<int> prev_col(n, -1);
    std::vector<double> dist(n);
    std::vector<int> pred(n);
    std::vector<int> seen_stamp(n, 0);   // 0 unseen, >0 in active or scanned
    std::vector<int> active(k * 8 + 16);
    std::vector<int> scanned(n);
    int stamp_gen = 1;

    for (int i = 0; i < n; ++i) {
        double m = INF;
        const double* row = nc + (long)i * k;
        for (int t = 0; t < k; ++t) if (row[t] < m) m = row[t];
        u[i] = m;
        v[i] = 0.0;
    }

    long relax_edges = 0, scan_cols = 0;
    auto t0 = std::chrono::high_resolution_clock::now();

    for (int i = 0; i < n; ++i) {
        if (stamp_gen > 1'000'000'000) {
            std::fill(seen_stamp.begin(), seen_stamp.end(), 0);
            stamp_gen = 1;
        }
        int my = stamp_gen++;
        int nactive = 0;
        int nscanned = 0;

        auto ensure = [&](int need) {
            if ((int)active.size() < need) active.resize(need);
        };

        const int* nj = nb + (long)i * k;
        const double* cij = nc + (long)i * k;
        double ui = u[i];
        ensure(k);
        for (int t = 0; t < k; ++t) {
            int j = nj[t];
            dist[j] = cij[t] - ui - v[j];
            pred[j] = i;
            seen_stamp[j] = my;
            active[nactive++] = j;
        }

        int free_col = -1;
        double delta = 0;
        while (true) {
            if (nactive == 0) {
                auto t1 = std::chrono::high_resolution_clock::now();
                return {false, std::chrono::duration<double, std::milli>(t1 - t0).count(), relax_edges, scan_cols};
            }
            int best_p = 0;
            double dmin = dist[active[0]];
            for (int p = 1; p < nactive; ++p) {
                double d = dist[active[p]];
                if (d < dmin) { dmin = d; best_p = p; }
            }
            int jmin = active[best_p];
            active[best_p] = active[--nactive];
            scanned[nscanned++] = jmin;
            // mark scanned by setting seen_stamp to -my? keep my and use a side flag.
            // We'll set seen_stamp[jmin] = -my to mean scanned.
            seen_stamp[jmin] = -my;
            ++scan_cols;

            int r = row_of_col[jmin];
            if (r < 0) { free_col = jmin; delta = dmin; break; }

            const int* rnj = nb + (long)r * k;
            const double* rnc = nc + (long)r * k;
            double base = dmin - u[r];
            relax_edges += k;
            ensure(nactive + k);
            for (int t = 0; t < k; ++t) {
                int j = rnj[t];
                int st = seen_stamp[j];
                if (st == -my) continue;          // scanned
                double cand = base + rnc[t] - v[j];
                if (st != my) {                   // unseen
                    dist[j] = cand;
                    pred[j] = r;
                    seen_stamp[j] = my;
                    active[nactive++] = j;
                } else if (cand < dist[j]) {
                    dist[j] = cand;
                    pred[j] = r;
                }
            }
        }

        // dual updates
        for (int s = 0; s < nscanned; ++s) {
            int j = scanned[s];
            v[j] += dist[j] - delta;
        }
        u[i] += delta;
        for (int s = 0; s < nscanned; ++s) {
            int j = scanned[s];
            int r = row_of_col[j];
            if (r >= 0) u[r] += delta - dist[j];
        }

        // augment
        int j = free_col;
        while (true) {
            int r = pred[j];
            int pj = prev_col[r];
            row_of_col[j] = r;
            prev_col[r] = j;
            if (r == i) break;
            j = pj;
        }
    }

    for (int j = 0; j < n; ++j) match_col[row_of_col[j]] = j;
    auto t1 = std::chrono::high_resolution_clock::now();
    return {true, std::chrono::duration<double, std::milli>(t1 - t0).count(), relax_edges, scan_cols};
}

// Reduced-cost violations against the FULL cost matrix. Returns worst violation (negative means violated)
// and the row/col of the worst.
double worst_violation(int n, const double* cost, const double* u, const double* v, int& wi, int& wj) {
    double worst = 0; // reduced cost minimum; optimality wants min >= -tol, violation = -min if min<0
    wi = wj = -1;
    double minrc = 1e300;
    for (int i = 0; i < n; ++i) {
        const double* row = cost + (long)i * n;
        double ui = u[i];
        for (int j = 0; j < n; ++j) {
            double rc = row[j] - ui - v[j];
            if (rc < minrc) { minrc = rc; wi = i; wj = j; }
        }
    }
    return minrc;
}

int main(int argc, char** argv) {
    int n = argc > 1 ? atoi(argv[1]) : 600;
    int k = argc > 2 ? atoi(argv[2]) : 80;
    int seed = argc > 3 ? atoi(argv[3]) : 0;
    std::mt19937 rng(seed);
    std::uniform_real_distribution<double> ud(0, 1);
    std::vector<double> sp(n * 2), tp(n * 2);
    for (int i = 0; i < n * 2; ++i) { sp[i] = ud(rng); tp[i] = ud(rng); }

    std::vector<double> cost((long)n * n);
    auto tb0 = std::chrono::high_resolution_clock::now();
    for (int i = 0; i < n; ++i) {
        double sx = sp[2 * i], sy = sp[2 * i + 1];
        double* row = cost.data() + (long)i * n;
        for (int j = 0; j < n; ++j) {
            double dx = sx - tp[2 * j], dy = sy - tp[2 * j + 1];
            row[j] = std::sqrt(dx * dx + dy * dy);
        }
    }
    std::vector<int> nb((long)n * k);
    std::vector<double> nc((long)n * k);
    std::vector<int> idx(n);
    for (int i = 0; i < n; ++i) {
        std::iota(idx.begin(), idx.end(), 0);
        const double* row = cost.data() + (long)i * n;
        std::nth_element(idx.begin(), idx.begin() + (k - 1), idx.end(),
                         [&](int a, int b) { return row[a] < row[b]; });
        for (int t = 0; t < k; ++t) {
            nb[(long)i * k + t] = idx[t];
            nc[(long)i * k + t] = row[idx[t]];
        }
    }
    auto tb1 = std::chrono::high_resolution_clock::now();

    std::vector<int> match(n);
    std::vector<double> u(n), v(n);
    Result r = sparse_jv(n, k, nb.data(), nc.data(), match.data(), u.data(), v.data());
    auto tp0 = std::chrono::high_resolution_clock::now();
    int wi, wj;
    double minrc = 1e300;
    if (r.ok) minrc = worst_violation(n, cost.data(), u.data(), v.data(), wi, wj);
    auto tp1 = std::chrono::high_resolution_clock::now();

    double s = 0;
    if (r.ok) for (int i = 0; i < n; ++i) s += cost[(long)i * n + match[i]];
    double mb = std::chrono::duration<double, std::milli>(tb1 - tb0).count();
    double mp = std::chrono::duration<double, std::milli>(tp1 - tp0).count();
    printf("n=%d k=%d ok=%d build=%.2f solve=%.2f price=%.2f cost=%.6f minrc=%.3e scans=%ld relax=%ld\n",
           n, k, (int)r.ok, mb, r.ms, mp, s, minrc, r.scan_cols, r.relax_edges);

    if (r.ok) {
        FILE* f = fopen("build/as.txt", "w");
        fprintf(f, "%d\n", n);
        for (int i = 0; i < n; ++i) fprintf(f, "%d\n", match[i]);
        fclose(f);
        FILE* fc = fopen("build/cost.bin", "wb");
        fwrite(cost.data(), 8, (long)n * n, fc);
        fclose(fc);
    }
    return r.ok ? 0 : 1;
}
