// Find all edges with reduced cost < -tol and append them. Returns count added and min reduced cost.
int add_violators(int n, const double* cost, const double* u, const double* v,
                  std::vector<std::vector<int>>& nb, std::vector<std::vector<double>>& nc,
                  std::vector<std::vector<char>>& has, double tol, double& minrc) {
    int added = 0;
    minrc = 1e300;
    for (int i = 0; i < n; ++i) {
        const double* row = cost + (long)i * n;
        double ui = u[i];
        auto& h = has[i];
        auto& rnb = nb[i];
        auto& rnc = nc[i];
        for (int j = 0; j < n; ++j) {
            double rc = row[j] - ui - v[j];
            if (rc < minrc) minrc = rc;
            if (rc < -tol && !h[j]) {
                h[j] = 1;
                rnb.push_back(j);
                rnc.push_back(row[j]);
                ++added;
            }
        }
    }
    return added;
}

