#include <algorithm>
#include <chrono>
#include <cmath>
#include <cstdio>
#include <cstdlib>
#include <numeric>
#include <random>
#include <vector>

// Warm-started sparse JV.
// If warm==false, initializes duals from row mins and empty matching.
// If warm==true, keeps u, v, and the current matching (match_col / implied),
// and only re-augments rows that are currently free. After adding edges the
// matching is still perfect, so a warm call with a perfect matching returns
// immediately — NOT what we want.
//
// To exploit new edges we must allow the duals to be repaired. Strategy:
//   Keep prices. Unmatch ALL rows (or unmatch rows incident to new edges) and
//   re-augment, but the initial reduced costs are already small so shortest
//   paths are short... actually unmatching all throws away the matching.
//
// Better: "dual-feasible repair". After adding negative reduced-cost edges,
// the duals are infeasible. One standard approach (cost-scaling / auction)
// isn't JV.
//
// Alternative JV warm start used by Jonker-Volgenant:
//   Keep the matching. For the new edges with negative reduced cost, they
//   indicate the duals aren't optimal. We can decrease u or increase v to
//   restore feasibility, which may break complementary slackness on matched
//   edges, then re-optimize.
//
// Simpler experiment: just time how fast a FRESH solve is with k=32 (one round)
// vs k=48 vs k=64, and separately time a warm re-solve that starts from the
// previous matching but allows one "improvement" pass.
//
// Practical warm start that DOES work:
//   1. Solve on kNN.
//   2. Find violators.
//   3. Instead of full restart, run a limited number of augmenting-path
//      improvements? Assignment improvement from a feasible matching:
//      for a negative cycle... hard.
//
// Let's try: keep duals, discard matching, re-run augmentation from scratch
// but with the GOOD duals. Shortest paths should be shorter because reduced
// costs are already near-optimal except for a few new edges. Measure scans.

struct Result { bool ok; double ms; long scans; };

Result sparse_jv(int n, const std::vector<std::vector<int>>& nb,
                 const std::vector<std::vector<double>>& nc,
                 int* match_col, double* u, double* v, bool init_duals) {
    const double INF = 1e100;
    std::vector<int> row_of_col(n, -1), prev_col(n, -1);
    std::vector<double> dist(n);
    std::vector<int> pred(n), seen(n, 0), active, scanned;
    active.reserve(8192); scanned.reserve(4096);
    int stamp_gen = 1;

    if (init_duals) {
        for (int i = 0; i < n; ++i) {
            double m = INF;
            for (double c : nc[i]) if (c < m) m = c;
            u[i] = m; v[i] = 0.0;
        }
    }

    long scans = 0;
    auto t0 = std::chrono::high_resolution_clock::now();
    for (int i = 0; i < n; ++i) {
        if (stamp_gen > 1000000000) { std::fill(seen.begin(), seen.end(), 0); stamp_gen = 1; }
        int my = stamp_gen++;
        active.clear(); scanned.clear();
        double ui = u[i];
        const auto& rnb = nb[i]; const auto& rnc = nc[i];
        for (int t = 0; t < (int)rnb.size(); ++t) {
            int j = rnb[t];
            dist[j] = rnc[t] - ui - v[j];
            pred[j] = i; seen[j] = my; active.push_back(j);
        }
        int free_col = -1; double delta = 0;
        while (true) {
            if (active.empty()) {
                auto t1 = std::chrono::high_resolution_clock::now();
                return {false, std::chrono::duration<double, std::milli>(t1-t0).count(), scans};
            }
            int best_p = 0; double dmin = dist[active[0]];
            for (int p = 1; p < (int)active.size(); ++p)
                if (dist[active[p]] < dmin) { dmin = dist[active[p]]; best_p = p; }
            int jmin = active[best_p];
            active[best_p] = active.back(); active.pop_back();
            scanned.push_back(jmin); seen[jmin] = -my; ++scans;
            int r = row_of_col[jmin];
            if (r < 0) { free_col = jmin; delta = dmin; break; }
            const auto& rnb2 = nb[r]; const auto& rnc2 = nc[r];
            double base = dmin - u[r];
            for (int t = 0; t < (int)rnb2.size(); ++t) {
