        double minrc; int added = add_violators(n, cost.data(), u.data(), v.data(), nb, nc, has, 1e-9, minrc);
        // round 2: KEEP duals (init_duals false) but matching rebuilt
        Result r2 = sparse_jv(n, nb, nc, match.data(), u.data(), v.data(), false);
        int added2 = add_violators(n, cost.data(), u.data(), v.data(), nb, nc, has, 1e-9, minrc);
        Result r3{true,0,0};
        if (added2) r3 = sparse_jv(n, nb, nc, match.data(), u.data(), v.data(), false);
        int added3 = 0;
        if (added2) added3 = add_violators(n, cost.data(), u.data(), v.data(), nb, nc, has, 1e-9, minrc);
        auto tB = std::chrono::high_resolution_clock::now();
        double all = std::chrono::duration<double,std::milli>(tB-tA).count();
        printf("seed=%d r1=%.2f scans1=%ld added1=%d | r2=%.2f scans2=%ld added2=%d | r3=%.2f scans3=%ld added3=%d | all=%.2f minrc=%.1e\n",
               seed+sidx, r1.ms, r1.scans, added, r2.ms, r2.scans, added2, r3.ms, r3.scans, added3, all, minrc);
    }
}
