#include <algorithm>
#include <chrono>
#include <cmath>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <numeric>
#include <random>
#include <vector>

// Fast sparse JV with:
//  - CSR neighbor lists (contiguous)
//  - warm-started duals across rounds
//  - active-set Dijkstra
//  - pricing that adds only violating edges

struct Result { bool ok; double ms; long scans; };

Result sparse_jv_csr(int n, const int* off, const int* cols, const double* costs,
                     int* match_col, double* u, double* v, bool init_duals) {
    const double INF = 1e100;
    std::vector<int> row_of_col(n, -1), prev_col(n, -1);
    std::vector<double> dist(n);
    std::vector<int> pred(n), seen(n, 0);
    std::vector<int> active; active.reserve(8192);
    std::vector<int> scanned; scanned.reserve(4096);
    int stamp_gen = 1;

    if (init_duals) {
        for (int i = 0; i < n; ++i) {
            double m = INF;
            for (int p = off[i]; p < off[i + 1]; ++p) if (costs[p] < m) m = costs[p];
            u[i] = m; v[i] = 0.0;
        }
    }

    long scans = 0;
    auto t0 = std::chrono::high_resolution_clock::now();
    for (int i = 0; i < n; ++i) {
        if (stamp_gen > 1000000000) { std::fill(seen.begin(), seen.end(), 0); stamp_gen = 1; }
        int my = stamp_gen++;
        active.clear(); scanned.clear();
        double ui = u[i];
        for (int p = off[i]; p < off[i + 1]; ++p) {
            int j = cols[p];
            dist[j] = costs[p] - ui - v[j];
            pred[j] = i; seen[j] = my; active.push_back(j);
        }
        int free_col = -1; double delta = 0;
        while (true) {
            int na = (int)active.size();
            if (!na) {
                auto t1 = std::chrono::high_resolution_clock::now();
                return {false, std::chrono::duration<double, std::milli>(t1 - t0).count(), scans};
            }
            int best_p = 0; double dmin = dist[active[0]];
            for (int p = 1; p < na; ++p) {
                double d = dist[active[p]];
                if (d < dmin) { dmin = d; best_p = p; }
            }
            int jmin = active[best_p];
            active[best_p] = active[--na];
            active.pop_back();
            scanned.push_back(jmin);
            seen[jmin] = -my;
            ++scans;
            int r = row_of_col[jmin];
            if (r < 0) { free_col = jmin; delta = dmin; break; }
            double base = dmin - u[r];
            for (int p = off[r]; p < off[r + 1]; ++p) {
                int j = cols[p];
                int st = seen[j];
                if (st == -my) continue;
                double cand = base + costs[p] - v[j];
                if (st != my) {
                    dist[j] = cand; pred[j] = r; seen[j] = my; active.push_back(j);
                } else if (cand < dist[j]) {
                    dist[j] = cand; pred[j] = r;
                }
            }
        }
        int ns = (int)scanned.size();
        for (int s = 0; s < ns; ++s) {
            int j = scanned[s];
            v[j] += dist[j] - delta;
        }
        u[i] += delta;
        for (int s = 0; s < ns; ++s) {
            int j = scanned[s];
            int r = row_of_col[j];
            if (r >= 0) u[r] += delta - dist[j];
        }
        int j = free_col;
        while (true) {
            int r = pred[j];
            int pj = prev_col[r];
            row_of_col[j] = r;
            prev_col[r] = j;
            if (r == i) break;
            j = pj;
        }
    }
    for (int j = 0; j < n; ++j) match_col[row_of_col[j]] = j;
    auto t1 = std::chrono::high_resolution_clock::now();
    return {true, std::chrono::duration<double, std::milli>(t1 - t0).count(), scans};
}

int main(int argc, char** argv) {
    int n = atoi(argv[1]);
    int k0 = atoi(argv[2]);
    int seed0 = atoi(argv[3]);
    int ns = atoi(argv[4]);
    double sum = 0;
    for (int sidx = 0; sidx < ns; ++sidx) {
        std::mt19937 rng(seed0 + sidx);
        std::uniform_real_distribution<double> ud(0, 1);
        std::vector<double> sp(n * 2), tp(n * 2);
        for (int i = 0; i < n * 2; ++i) { sp[i] = ud(rng); tp[i] = ud(rng); }

        auto tA = std::chrono::high_resolution_clock::now();
        std::vector<double> cost((long)n * n);
        for (int i = 0; i < n; ++i) {
            double sx = sp[2 * i], sy = sp[2 * i + 1];
            double* row = cost.data() + (long)i * n;
            for (int j = 0; j < n; ++j) {
                double dx = sx - tp[2 * j], dy = sy - tp[2 * j + 1];
                row[j] = std::sqrt(dx * dx + dy * dy);
            }
        }
        // build initial kNN as CSR, with room to append
        // We'll use vectors and rebuild CSR each round? Appending to CSR is awkward.
        // Use per-row vectors then flatten once per round — flatten is cheap.
        std::vector<std::vector<int>> nb(n);
        std::vector<std::vector<double>> nc(n);
        std::vector<uint8_t> has((long)n * n, 0);
        std::vector<int> idx(n);
        for (int i = 0; i < n; ++i) {
            std::iota(idx.begin(), idx.end(), 0);
            const double* row = cost.data() + (long)i * n;
            std::nth_element(idx.begin(), idx.begin() + (k0 - 1), idx.end(),
                             [&](int a, int b) { return row[a] < row[b]; });
            nb[i].reserve(k0 + 64); nc[i].reserve(k0 + 64);
            for (int t = 0; t < k0; ++t) {
                int j = idx[t];
                nb[i].push_back(j); nc[i].push_back(row[j]);
                has[(long)i * n + j] = 1;
            }
        }

        std::vector<int> off(n + 1), cols; std::vector<double> costs;
        auto flatten = [&]() {
            off[0] = 0;
            int total = 0;
            for (int i = 0; i < n; ++i) total += (int)nb[i].size();
            cols.resize(total); costs.resize(total);
            int p = 0;
            for (int i = 0; i < n; ++i) {
                for (int t = 0; t < (int)nb[i].size(); ++t) {
                    cols[p] = nb[i][t];
                    costs[p] = nc[i][t];
                    ++p;
                }
                off[i + 1] = p;
            }
        };

        std::vector<int> match(n);
        std::vector<double> u(n), v(n);
        bool init = true;
        int rounds = 0; double solve = 0; bool ok = true; double minrc = 0; int added_total = 0;
        while (rounds < 12) {
            flatten();
            Result r = sparse_jv_csr(n, off.data(), cols.data(), costs.data(), match.data(), u.data(), v.data(), init);
            init = false; solve += r.ms; ++rounds;
            if (!r.ok) { ok = false; break; }
            int added = 0; minrc = 1e300;
            for (int i = 0; i < n; ++i) {
                const double* row = cost.data() + (long)i * n;
                double ui = u[i];
                uint8_t* h = has.data() + (long)i * n;
                for (int j = 0; j < n; ++j) {
                    double rc = row[j] - ui - v[j];
                    if (rc < minrc) minrc = rc;
                    if (rc < -1e-8 && !h[j]) {
                        h[j] = 1; nb[i].push_back(j); nc[i].push_back(row[j]); ++added;
                    }
                }
            }
            added_total += added;
            if (!added) break;
        }
        auto tB = std::chrono::high_resolution_clock::now();
        double all = std::chrono::duration<double, std::milli>(tB - tA).count();
        sum += all;
        double s = 0;
        if (ok) for (int i = 0; i < n; ++i) s += cost[(long)i * n + match[i]];
        printf("seed=%d ok=%d rounds=%d all=%.2f solve=%.2f added=%d minrc=%.1e cost=%.6f\n",
               seed0 + sidx, (int)ok, rounds, all, solve, added_total, minrc, s);
        if (sidx == 0) {
            FILE* f = fopen("build/as.txt", "w");
            fprintf(f, "%d\n", n);
            for (int i = 0; i < n; ++i) fprintf(f, "%d\n", match[i]);
            fclose(f);
            FILE* fc = fopen("build/cost.bin", "wb");
            fwrite(cost.data(), 8, (long)n * n, fc); fclose(fc);
        }
    }
    printf("AVG %.2f ms\n", sum / ns);
}
