struct Result { bool ok; double ms; long scans; long heap_ops; };

Result sparse_jv_heap(int n, const std::vector<std::vector<int>>& nb,
                      const std::vector<std::vector<double>>& nc,
                      int* match_col, double* u, double* v, bool init_duals) {
    const double INF = 1e100;
    std::vector<int> row_of_col(n, -1), prev_col(n, -1);
    std::vector<double> dist(n);
    std::vector<int> pred(n), seen(n, 0);
    std::vector<int> scanned; scanned.reserve(1024);
    int stamp_gen = 1;
    if (init_duals) {
        for (int i = 0; i < n; ++i) {
            double m = INF;
            for (double c : nc[i]) if (c < m) m = c;
            u[i] = m; v[i] = 0;
        }
    }
    long scans = 0, hops = 0;
    auto t0 = std::chrono::high_resolution_clock::now();

    // binary heap of (dist, col) with lazy deletion: a node is valid if dist matches
    struct Node { double d; int j; };
    std::vector<Node> heap;
    heap.reserve(4096);
    auto push = [&](double d, int j) {
        heap.push_back({d, j});
        int i = (int)heap.size() - 1;
        while (i > 0) {
            int p = (i - 1) >> 1;
            if (heap[p].d <= heap[i].d) break;
            std::swap(heap[p], heap[i]);
            i = p;
        }
        ++hops;
    };
    auto pop_min = [&](int my) -> int {
        while (!heap.empty()) {
            Node nd = heap[0];
            // sift down pop
            heap[0] = heap.back(); heap.pop_back();
            int i = 0, sz = (int)heap.size();
            while (true) {
                int l = i * 2 + 1, r = l + 1, b = i;
                if (l < sz && heap[l].d < heap[b].d) b = l;
                if (r < sz && heap[r].d < heap[b].d) b = r;
                if (b == i) break;
                std::swap(heap[i], heap[b]);
                i = b;
            }
            ++hops;
            if (seen[nd.j] == -my) continue;          // already scanned
            if (nd.d != dist[nd.j]) continue;         // stale
            return nd.j;
        }
        return -1;
    };

    for (int i = 0; i < n; ++i) {
        if (stamp_gen > 1000000000) { std::fill(seen.begin(), seen.end(), 0); stamp_gen = 1; }
        int my = stamp_gen++;
        heap.clear(); scanned.clear();
        double ui = u[i];
        const auto& rnb = nb[i]; const auto& rnc = nc[i];
        for (int t = 0; t < (int)rnb.size(); ++t) {
            int j = rnb[t];
            dist[j] = rnc[t] - ui - v[j];
            pred[j] = i; seen[j] = my;
            push(dist[j], j);
        }
        int free_col = -1; double delta = 0;
        while (true) {
            int jmin = pop_min(my);
            if (jmin < 0) {
                auto t1 = std::chrono::high_resolution_clock::now();
                return {false, std::chrono::duration<double,std::milli>(t1-t0).count(), scans, hops};
            }
            seen[jmin] = -my;
            scanned.push_back(jmin);
            ++scans;
            delta = dist[jmin];
            int r = row_of_col[jmin];
            if (r < 0) { free_col = jmin; break; }
            const auto& rnb2 = nb[r]; const auto& rnc2 = nc[r];
            double base = delta - u[r];
            for (int t = 0; t < (int)rnb2.size(); ++t) {
                int j = rnb2[t];
                int st = seen[j];
                if (st == -my) continue;
                double cand = base + rnc2[t] - v[j];
                if (st != my) {
                    dist[j] = cand; pred[j] = r; seen[j] = my; push(cand, j);
                } else if (cand < dist[j]) {
                    dist[j] = cand; pred[j] = r; push(cand, j);
                }
            }
        }
        for (int j : scanned) v[j] += dist[j] - delta;
        u[i] += delta;
        for (int j : scanned) { int r = row_of_col[j]; if (r >= 0) u[r] += delta - dist[j]; }
        int j = free_col;
        while (true) {
            int r = pred[j]; int pj = prev_col[r];
            row_of_col[j] = r; prev_col[r] = j;
            if (r == i) break; j = pj;
        }
    }
    for (int j = 0; j < n; ++j) match_col[row_of_col[j]] = j;
    auto t1 = std::chrono::high_resolution_clock::now();
    return {true, std::chrono::duration<double,std::milli>(t1-t0).count(), scans, hops};
}

int add_violators(int n, const double* cost, const double* u, const double* v,
                  std::vector<std::vector<int>>& nb, std::vector<std::vector<double>>& nc,
                  std::vector<uint8_t>& has, double tol, double& minrc) {
    int added = 0; minrc = 1e300;
    for (int i = 0; i < n; ++i) {
        const double* row = cost + (long)i * n;
        double ui = u[i];
        uint8_t* h = has.data() + (long)i * n;
        for (int j = 0; j < n; ++j) {
            double rc = row[j] - ui - v[j];
            if (rc < minrc) minrc = rc;
            if (rc < -tol && !h[j]) { h[j] = 1; nb[i].push_back(j); nc[i].push_back(row[j]); ++added; }
        }
    }
    return added;
}

int main(int argc, char** argv) {
    int n=atoi(argv[1]), k0=atoi(argv[2]), seed0=atoi(argv[3]), ns=atoi(argv[4]);
    double sum=0;
    for (int sidx=0;sidx<ns;sidx++) {
        std::mt19937 rng(seed0+sidx);
        std::uniform_real_distribution<double> ud(0,1);
        std::vector<double> sp(n*2), tp(n*2);
        for (int i=0;i<n*2;i++){sp[i]=ud(rng);tp[i]=ud(rng);}
        auto tA=std::chrono::high_resolution_clock::now();
        std::vector<double> cost((long)n*n);
        for (int i=0;i<n;i++){
            double sx=sp[2*i], sy=sp[2*i+1];
            double* row=cost.data()+(long)i*n;
            for (int j=0;j<n;j++){
                double dx=sx-tp[2*j], dy=sy-tp[2*j+1];
                row[j]=std::sqrt(dx*dx+dy*dy);
            }
        }
        std::vector<std::vector<int>> nb(n);
        std::vector<std::vector<double>> nc(n);
        std::vector<uint8_t> has((long)n*n,0);
        std::vector<int> idx(n);
        for (int i=0;i<n;i++){
            std::iota(idx.begin(),idx.end(),0);
            const double* row=cost.data()+(long)i*n;
            std::nth_element(idx.begin(), idx.begin()+(k0-1), idx.end(), [&](int a,int b){return row[a]<row[b];});
            nb[i].reserve(k0+32); nc[i].reserve(k0+32);
            for (int t=0;t<k0;t++){ int j=idx[t]; nb[i].push_back(j); nc[i].push_back(row[j]); has[(long)i*n+j]=1; }
        }
        std::vector<int> match(n); std::vector<double> u(n), v(n);
        bool init=true; int rounds=0; double solve=0; bool ok=true; double minrc=0; int added_total=0; long scans=0;
        while (rounds<12) {
            Result r = sparse_jv_heap(n, nb, nc, match.data(), u.data(), v.data(), init);
            init=false; solve+=r.ms; scans+=r.scans; ++rounds;
            if (!r.ok){ok=false; break;}
            int added = add_violators(n, cost.data(), u.data(), v.data(), nb, nc, has, 1e-8, minrc);
            added_total += added;
            if (!added) break;
        }
        auto tB=std::chrono::high_resolution_clock::now();
        double all=std::chrono::duration<double,std::milli>(tB-tA).count();
        sum+=all;
        printf("seed=%d ok=%d rounds=%d all=%.2f solve=%.2f scans=%ld added=%d minrc=%.1e\n",
               seed0+sidx,(int)ok,rounds,all,solve,scans,added_total,minrc);
        if (sidx==0) {
            FILE* f=fopen("build/as.txt","w"); fprintf(f,"%d\n",n);
            for(int i=0;i<n;i++) fprintf(f,"%d\n", match[i]); fclose(f);
            FILE* fc=fopen("build/cost.bin","wb"); fwrite(cost.data(),8,(long)n*n,fc); fclose(fc);
        }
    }
    printf("AVG %.2f\n", sum/ns);
}
