#include <algorithm>
#include <chrono>
#include <cmath>
#include <cstdio>
#include <cstdlib>
#include <random>
#include <vector>

// Dense auction, epsilon-scaling. Reports time and whether assignment is a permutation.
void auction(int n, const double* cost, int* assign, double eps_final, double factor, int& phases, long& iters) {
    std::vector<double> price(n, 0.0);
    std::vector<int> owner(n, -1);
    double cmax = 0;
    for (long i = 0; i < (long)n * n; ++i) cmax = std::max(cmax, cost[i]);
    // start eps relative to mean cost / n? Bertsekas recommends eps0 large.
    double eps = cmax * 0.5;
    phases = 0; iters = 0;
    while (true) {
        std::fill(owner.begin(), owner.end(), -1);
        std::fill(assign, assign + n, -1);
        // cyclic bidding over unassigned — use a queue
        std::vector<int> freeq(n);
        for (int i = 0; i < n; ++i) freeq[i] = i;
        int head = 0, tail = n;
        // we'll just use a stack-like vector
        while (head < tail) {
            int i = freeq[head++];
            const double* row = cost + (long)i * n;
            int best_j = 0;
            double best = -(row[0] + price[0]);
            double second = -1e300;
            for (int j = 1; j < n; ++j) {
                double val = -(row[j] + price[j]);
                if (val > best) { second = best; best = val; best_j = j; }
                else if (val > second) second = val;
            }
            price[best_j] += best - second + eps;
            int prev = owner[best_j];
            owner[best_j] = i;
            assign[i] = best_j;
            ++iters;
            if (prev >= 0) {
                assign[prev] = -1;
                if (tail == (int)freeq.size()) freeq.push_back(prev);
                else freeq[tail] = prev;
                // actually freeq may not have capacity if we only sized n. Use push.
            }
        }
        // The above queue logic is wrong if we use head/tail with fixed buffer and also push.
        // Rewrite more simply below if this is buggy — I'll use a vector stack instead.
        ++phases;
        if (eps <= eps_final) break;
        eps *= factor;
        if (eps < eps_final) eps = eps_final;
        if (phases > 40) break;
        // reset for next phase is at loop top
        // BUG: freeq logic above doesn't requeue properly. Fixing by not using this function body.
        break;
    }
}

// Clean implementation
void auction2(int n, const double* cost, int* assign, double eps_final, double factor,
              int& phases, long& iters) {
    std::vector<double> price(n, 0.0);
    std::vector<int> owner(n, -1);
    double cmax = 0;
    for (long i = 0; i < (long)n * n; ++i) if (cost[i] > cmax) cmax = cost[i];
    double eps = cmax * 0.5 + 1e-15;
    phases = 0; iters = 0;
    std::vector<int> free_rows;
    free_rows.reserve(n * 2);
    while (true) {
        std::fill(owner.begin(), owner.end(), -1);
        std::fill(assign, assign + n, -1);
        free_rows.clear();
        for (int i = n - 1; i >= 0; --i) free_rows.push_back(i);
        while (!free_rows.empty()) {
            int i = free_rows.back(); free_rows.pop_back();
            const double* row = cost + (long)i * n;
            int best_j = 0;
            double best = -(row[0] + price[0]);
            double second = -1e300;
            for (int j = 1; j < n; ++j) {
                double val = -(row[j] + price[j]);
                if (val > best) { second = best; best = val; best_j = j; }
                else if (val > second) second = val;
            }
            price[best_j] += (best - second) + eps;
            int prev = owner[best_j];
            owner[best_j] = i;
            assign[i] = best_j;
            ++iters;
            if (prev >= 0) free_rows.push_back(prev);
        }
        ++phases;
        if (eps <= eps_final) break;
        eps *= factor;
        if (eps < eps_final) eps = eps_final;
        if (phases > 50) break;
    }
}

int main(int argc, char** argv) {
    int n = argc > 1 ? atoi(argv[1]) : 600;
    double factor = argc > 2 ? atof(argv[2]) : 0.25;
    double eps_final = argc > 3 ? atof(argv[3]) : 1e-9;
    int seed = argc > 4 ? atoi(argv[4]) : 0;
    std::mt19937 rng(seed);
    std::uniform_real_distribution<double> ud(0, 1);
    std::vector<double> sp(n * 2), tp(n * 2);
    for (int i = 0; i < n * 2; ++i) { sp[i] = ud(rng); tp[i] = ud(rng); }
    std::vector<double> cost((long)n * n);
    auto tA = std::chrono::high_resolution_clock::now();
    for (int i = 0; i < n; ++i) {
        double sx = sp[2 * i], sy = sp[2 * i + 1];
        double* row = cost.data() + (long)i * n;
        for (int j = 0; j < n; ++j) {
            double dx = sx - tp[2 * j], dy = sy - tp[2 * j + 1];
            row[j] = std::sqrt(dx * dx + dy * dy);
        }
    }
    std::vector<int> assign(n);
    int phases = 0; long iters = 0;
    auto t0 = std::chrono::high_resolution_clock::now();
    auction2(n, cost.data(), assign.data(), eps_final, factor, phases, iters);
    auto t1 = std::chrono::high_resolution_clock::now();
    double s = 0; int bad = 0;
    std::vector<char> used(n, 0);
    for (int i = 0; i < n; ++i) {
        int j = assign[i];
        if (j < 0 || j >= n || used[j]) bad++;
        else { used[j] = 1; s += cost[(long)i * n + j]; }
    }
    double ms = std::chrono::duration<double, std::milli>(t1 - t0).count();
    double build = std::chrono::duration<double, std::milli>(t0 - tA).count();
    printf("n=%d factor=%.3f eps=%g phases=%d iters=%ld build=%.2f solve=%.2f cost=%.8f bad=%d\n",
           n, factor, eps_final, phases, iters, build, ms, s, bad);
    FILE* f = fopen("build/as.txt", "w");
    fprintf(f, "%d\n", n);
    for (int i = 0; i < n; ++i) fprintf(f, "%d\n", assign[i]);
    fclose(f);
    FILE* fc = fopen("build/cost.bin", "wb");
    fwrite(cost.data(), 8, (long)n * n, fc); fclose(fc);
}
