#include <algorithm>
#include <chrono>
#include <cmath>
#include <cstdio>
#include <cstdlib>
#include <random>
#include <vector>
#include <limits>

// Column reduction + dense shortest path augmentation, counting scans.
// This is a correct JV if dual updates are right. We'll verify cost vs a saved scipy solution later.

int main(int argc, char** argv) {
    int n = argc > 1 ? atoi(argv[1]) : 600;
    int seed = argc > 2 ? atoi(argv[2]) : 0;
    int ns = argc > 3 ? atoi(argv[3]) : 5;
    for (int sidx = 0; sidx < ns; ++sidx) {
        std::mt19937 rng(seed + sidx);
        std::uniform_real_distribution<double> ud(0, 1);
        std::vector<double> sp(n * 2), tp(n * 2);
        for (int i = 0; i < n * 2; ++i) { sp[i] = ud(rng); tp[i] = ud(rng); }
        std::vector<double> cost((long)n * n);
        for (int i = 0; i < n; ++i) {
            double sx = sp[2 * i], sy = sp[2 * i + 1];
            double* row = cost.data() + (long)i * n;
            for (int j = 0; j < n; ++j) {
                double dx = sx - tp[2 * j], dy = sy - tp[2 * j + 1];
                row[j] = std::sqrt(dx * dx + dy * dy);
            }
        }
        const double INF = 1e100;
        std::vector<double> u(n, 0.0), v(n, 0.0);
        std::vector<int> row_of_col(n, -1), col_of_row(n, -1);
        std::vector<int> free_rows;

        auto t0 = std::chrono::high_resolution_clock::now();

        // Row reduction: u[i] = min_j cost[i,j]
        for (int i = 0; i < n; ++i) {
            const double* row = cost.data() + (long)i * n;
            double m = row[0];
            for (int j = 1; j < n; ++j) if (row[j] < m) m = row[j];
            u[i] = m;
        }
        // Column reduction: for each column, find min reduced cost and assign if row free.
        // Process columns in order; also set v[j].
        for (int j = 0; j < n; ++j) {
            double best = INF; int bi = -1;
            for (int i = 0; i < n; ++i) {
                double rc = cost[(long)i * n + j] - u[i];
                if (rc < best) { best = rc; bi = i; }
            }
            v[j] = best;
            if (col_of_row[bi] < 0) {
                col_of_row[bi] = j;
                row_of_col[j] = bi;
            }
        }
        int assigned = 0;
        for (int i = 0; i < n; ++i) if (col_of_row[i] >= 0) assigned++;
        for (int i = 0; i < n; ++i) if (col_of_row[i] < 0) free_rows.push_back(i);

        // Augment free rows with dense shortest paths, but only scan columns that get finite dist.
        // Use an active list. Initialize dist only for... all columns are reachable.
        // To exploit small trees: use a threshold. We'll still find min among unscanned with a linear scan
        // over ALL columns — that's the baseline. Also count how many columns have dist < INF before we
        // could have stopped? For dense, all columns get a dist from the first row immediately.
        // So active = n always for dense. The "small tree" only helps if we use sparse candidates.
        //
        // Measure: during Dijkstra, how many columns are scanned before hitting a free column?
        std::vector<double> dist(n);
        std::vector<int> pred(n);
        std::vector<char> scanned(n);
        std::vector<int> prev_col(n, -1);
        for (int i = 0; i < n; ++i) if (col_of_row[i] >= 0) prev_col[i] = col_of_row[i];

        long total_scans = 0;
        int aug = 0;
        for (int fi = 0; fi < (int)free_rows.size(); ++fi) {
            int i = free_rows[fi];
            std::fill(scanned.begin(), scanned.end(), 0);
            const double* row = cost.data() + (long)i * n;
            double ui = u[i];
            for (int j = 0; j < n; ++j) {
                dist[j] = row[j] - ui - v[j];
                pred[j] = i;
            }
            int free_col = -1; double delta = 0; int nscan = 0;
            while (true) {
                double dmin = INF; int jmin = -1;
                for (int j = 0; j < n; ++j) if (!scanned[j] && dist[j] < dmin) { dmin = dist[j]; jmin = j; }
                scanned[jmin] = 1; ++nscan;
                int r = row_of_col[jmin];
                if (r < 0) { free_col = jmin; delta = dmin; break; }
                const double* rrow = cost.data() + (long)r * n;
                double base = dmin - u[r];
                for (int j = 0; j < n; ++j) {
                    if (scanned[j]) continue;
                    double cand = base + rrow[j] - v[j];
                    if (cand < dist[j]) { dist[j] = cand; pred[j] = r; }
                }
            }
            total_scans += nscan; ++aug;
            for (int j = 0; j < n; ++j) if (scanned[j]) v[j] += dist[j] - delta;
            u[i] += delta;
            for (int j = 0; j < n; ++j) {
                if (!scanned[j]) continue;
                int r = row_of_col[j];
                if (r >= 0) u[r] += delta - dist[j];
            }
            int j = free_col;
            while (true) {
                int r = pred[j];
                int pj = prev_col[r];
                row_of_col[j] = r;
                col_of_row[r] = j;
                prev_col[r] = j;
                if (r == i) break;
                j = pj;
            }
        }
        auto t1 = std::chrono::high_resolution_clock::now();
        double ms = std::chrono::duration<double, std::milli>(t1 - t0).count();
        double s = 0; int bad = 0;
        std::vector<char> used(n, 0);
        for (int i = 0; i < n; ++i) {
            int j = col_of_row[i];
            if (j < 0 || used[j]) bad++;
            else { used[j] = 1; s += cost[(long)i * n + j]; }
