#include <algorithm>
#include <chrono>
#include <cmath>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <numeric>
#include <random>
#include <vector>

struct Result { bool ok; double ms; int rounds; double minrc; };

Result solve(int n, int k0, const double* cost, int* col_of_row) {
    const double INF = 1e100;
    std::vector<std::vector<int>> nb(n);
    std::vector<std::vector<double>> nc(n);
    std::vector<uint8_t> has((long)n * n, 0);
    std::vector<int> idx(n);
    for (int i = 0; i < n; ++i) {
        std::iota(idx.begin(), idx.end(), 0);
        const double* row = cost + (long)i * n;
        std::nth_element(idx.begin(), idx.begin() + (k0 - 1), idx.end(),
                         [&](int a, int b) { return row[a] < row[b]; });
        nb[i].reserve(k0 + 32);
        nc[i].reserve(k0 + 32);
        for (int t = 0; t < k0; ++t) {
            int j = idx[t];
            nb[i].push_back(j);
            nc[i].push_back(row[j]);
            has[(long)i * n + j] = 1;
        }
    }

    std::vector<double> u(n), v(n, 0.0);
    std::vector<int> row_of_col(n, -1), prev_col(n, -1);
    std::vector<double> dist(n);
    std::vector<int> pred(n), seen(n, 0);
    std::vector<int> active; active.reserve(2048);
    std::vector<int> scanned; scanned.reserve(512);
    int stamp_gen = 1;

    auto augment_free = [&](const std::vector<int>& free_rows) -> bool {
        for (int i : free_rows) {
            if (stamp_gen > 1000000000) { std::fill(seen.begin(), seen.end(), 0); stamp_gen = 1; }
            int my = stamp_gen++;
            active.clear(); scanned.clear();
            double ui = u[i];
            const auto& rnb = nb[i]; const auto& rnc = nc[i];
            for (int t = 0; t < (int)rnb.size(); ++t) {
                int j = rnb[t];
                dist[j] = rnc[t] - ui - v[j];
                pred[j] = i; seen[j] = my; active.push_back(j);
            }
            int free_col = -1; double delta = 0;
            while (true) {
                int na = (int)active.size();
                if (!na) return false;
                int best_p = 0; double dmin = dist[active[0]];
                for (int p = 1; p < na; ++p) if (dist[active[p]] < dmin) { dmin = dist[active[p]]; best_p = p; }
                int jmin = active[best_p];
                active[best_p] = active[--na]; active.pop_back();
                scanned.push_back(jmin); seen[jmin] = -my;
                int r = row_of_col[jmin];
                if (r < 0) { free_col = jmin; delta = dmin; break; }
                const auto& rnb2 = nb[r]; const auto& rnc2 = nc[r];
                double base = dmin - u[r];
                for (int t = 0; t < (int)rnb2.size(); ++t) {
                    int j = rnb2[t]; int st = seen[j];
                    if (st == -my) continue;
                    double cand = base + rnc2[t] - v[j];
                    if (st != my) { dist[j] = cand; pred[j] = r; seen[j] = my; active.push_back(j); }
                    else if (cand < dist[j]) { dist[j] = cand; pred[j] = r; }
                }
            }
            for (int j : scanned) v[j] += dist[j] - delta;
            u[i] += delta;
            for (int j : scanned) { int r = row_of_col[j]; if (r >= 0) u[r] += delta - dist[j]; }
            int j = free_col;
            while (true) {
                int r = pred[j]; int pj = prev_col[r];
                row_of_col[j] = r; prev_col[r] = j;
                if (r == i) break; j = pj;
            }
        }
        return true;
    };

    auto t0 = std::chrono::high_resolution_clock::now();
    // init duals from kNN mins
    for (int i = 0; i < n; ++i) {
        double m = INF;
        for (double c : nc[i]) if (c < m) m = c;
        u[i] = m;
    }
    // column reduction on sparse edges only: each column's best reduced among rows that list it.
    // Build reverse lists.
    std::vector<std::vector<int>> rev(n);
    for (int i = 0; i < n; ++i) for (int j : nb[i]) rev[j].push_back(i);
    std::vector<int> free_rows;
    for (int j = 0; j < n; ++j) {
        double best = INF; int bi = -1;
        for (int i : rev[j]) {
            // find cost
            // linear search in nb[i] — degree ~32, ok once
            double c = 0;
            const auto& rnb = nb[i]; const auto& rnc = nc[i];
            for (int t = 0; t < (int)rnb.size(); ++t) if (rnb[t] == j) { c = rnc[t]; break; }
            double rc = c - u[i];
            if (rc < best) { best = rc; bi = i; }
        }
        if (bi < 0) continue;
        v[j] = best;
        if (prev_col[bi] < 0) {
            prev_col[bi] = j;
            row_of_col[j] = bi;
        }
    }
    for (int i = 0; i < n; ++i) if (prev_col[i] < 0) free_rows.push_back(i);
    int initial_free = (int)free_rows.size();

    int rounds = 0; double minrc = 0; bool ok = true;
    while (rounds < 12) {
        if (!augment_free(free_rows)) { ok = false; break; }
        ++rounds;
        // price
        int added = 0; minrc = 1e300;
        free_rows.clear();
        // After a perfect matching, duals may violate. Adding edges requires reoptimization.
        // We unmatch everyone? No — warm restart: discard matching but KEEP duals, re-column-reduce? 
        // Simpler: if violators exist, unmatch all and re-augment with kept duals (known fast).
        for (int i = 0; i < n; ++i) {
            const double* row = cost + (long)i * n;
            double ui = u[i];
            uint8_t* h = has.data() + (long)i * n;
            for (int j = 0; j < n; ++j) {
                double rc = row[j] - ui - v[j];
                if (rc < minrc) minrc = rc;
                if (rc < -1e-8 && !h[j]) {
                    h[j] = 1; nb[i].push_back(j); nc[i].push_back(row[j]); ++added;
                }
            }
        }
        if (!added) break;
        // reset matching, keep duals
        std::fill(row_of_col.begin(), row_of_col.end(), -1);
        std::fill(prev_col.begin(), prev_col.end(), -1);
        free_rows.resize(n);
        std::iota(free_rows.begin(), free_rows.end(), 0);
    }
    for (int j = 0; j < n; ++j) if (row_of_col[j] >= 0) col_of_row[row_of_col[j]] = j;
    auto t1 = std::chrono::high_resolution_clock::now();
    double ms = std::chrono::duration<double, std::milli>(t1 - t0).count();
    (void)initial_free;
    return {ok, ms, rounds, minrc};
}

int main(int argc, char** argv) {
    int n = atoi(argv[1]), k0 = atoi(argv[2]), seed0 = atoi(argv[3]), ns = atoi(argv[4]);
    double sum = 0;
    for (int sidx = 0; sidx < ns; ++sidx) {
        std::mt19937 rng(seed0 + sidx);
        std::uniform_real_distribution<double> ud(0, 1);
        std::vector<double> sp(n * 2), tp(n * 2);
        for (int i = 0; i < n * 2; ++i) { sp[i] = ud(rng); tp[i] = ud(rng); }
        auto tA = std::chrono::high_resolution_clock::now();
        std::vector<double> cost((long)n * n);
        for (int i = 0; i < n; ++i) {
            double sx = sp[2 * i], sy = sp[2 * i + 1];
            double* row = cost.data() + (long)i * n;
            for (int j = 0; j < n; ++j) {
                double dx = sx - tp[2 * j], dy = sy - tp[2 * j + 1];
                row[j] = std::sqrt(dx * dx + dy * dy);
            }
        }
        std::vector<int> col(n, -1);
        Result r = solve(n, k0, cost.data(), col.data());
        auto tB = std::chrono::high_resolution_clock::now();
        double all = std::chrono::duration<double, std::milli>(tB - tA).count();
        sum += all;
        double s = 0; int bad = 0; std::vector<char> used(n, 0);
        if (r.ok) for (int i = 0; i < n; ++i) {
            int j = col[i];
            if (j < 0 || j >= n || used[j]) bad++;
            else { used[j] = 1; s += cost[(long)i * n + j]; }
        }
        printf("seed=%d ok=%d bad=%d rounds=%d solve=%.2f all=%.2f minrc=%.1e cost=%.6f\n",
               seed0 + sidx, (int)r.ok, bad, r.rounds, r.ms, all, r.minrc, s);
        if (sidx == 0) {
            FILE* f = fopen("build/as.txt", "w"); fprintf(f, "%d\n", n);
            for (int i = 0; i < n; ++i) fprintf(f, "%d\n", col[i]); fclose(f);
            FILE* fc = fopen("build/cost.bin", "wb"); fwrite(cost.data(), 8, (long)n * n, fc); fclose(fc);
        }
    }
    printf("AVG all %.2f\n", sum / ns);
}
