#include <algorithm>
#include <atomic>
#include <chrono>
#include <cmath>
#include <cstdio>
#include <cstdlib>
#include <random>
#include <thread>
#include <vector>

// Parallel Jacobi (Gauss-Seidel-ish) auction:
// each thread owns a subset of rows and bids using atomic column prices.
// Epsilon scaling. This is the "synchronous Jacobi" auction which is known to
// converge, though possibly slower in iteration count than Gauss-Seidel.
// We do synchronous rounds: all free persons compute bids from a snapshot of prices,
// then we apply the highest bid per column.

void auction_jacobi(int n, const double* cost, int* assign, int threads, double eps_final, double factor,
                    int& phases, long& bids) {
    std::vector<double> price(n, 0.0);
    std::vector<int> owner(n, -1);
    double cmax = 0;
    for (long i = 0; i < (long)n * n; ++i) if (cost[i] > cmax) cmax = cost[i];
    double eps = cmax * 0.5;
    phases = 0; bids = 0;

    while (true) {
        std::fill(owner.begin(), owner.end(), -1);
        std::fill(assign, assign + n, -1);
        std::vector<char> free(n, 1);
        int nfree = n;
        int guard = 0;
        while (nfree > 0 && guard++ < n * 30) {
            // each free person computes best column and bid
            std::vector<int> bid_j(n, -1);
            std::vector<double> bid_inc(n, 0);
            std::vector<std::thread> ts;
            int chunk = (n + threads - 1) / threads;
            for (int t = 0; t < threads; ++t) {
                int lo = t * chunk, hi = std::min(n, lo + chunk);
                ts.emplace_back([&, lo, hi]() {
                    for (int i = lo; i < hi; ++i) {
                        if (!free[i]) continue;
                        const double* row = cost + (long)i * n;
                        int best_j = 0;
                        double best = -(row[0] + price[0]);
                        double second = -1e300;
                        for (int j = 1; j < n; ++j) {
                            double val = -(row[j] + price[j]);
                            if (val > best) { second = best; best = val; best_j = j; }
                            else if (val > second) second = val;
                        }
                        bid_j[i] = best_j;
                        bid_inc[i] = best - second + eps;
                    }
                });
            }
            for (auto& th : ts) th.join();

            // apply highest bid per column
            std::vector<int> winner(n, -1);
            std::vector<double> bestbid(n, -1);
            for (int i = 0; i < n; ++i) {
                if (!free[i]) continue;
                int j = bid_j[i];
                double inc = bid_inc[i];
                ++bids;
                if (inc > bestbid[j]) { bestbid[j] = inc; winner[j] = i; }
            }
            std::fill(free.begin(), free.end(), 0);
            nfree = 0;
            for (int j = 0; j < n; ++j) {
                int i = winner[j];
                if (i < 0) continue;
                price[j] += bestbid[j];
                int prev = owner[j];
                owner[j] = i;
                assign[i] = j;
                if (prev >= 0 && prev != i) {
                    free[prev] = 1; ++nfree; assign[prev] = -1;
                }
            }
            // persons who bid but lost
            for (int i = 0; i < n; ++i) {
                if (bid_j[i] >= 0 && assign[i] < 0 && !free[i]) {
                    // was free and didn't win
                    // only if they were free this round
                }
            }
            // recompute free properly: anyone unassigned
            nfree = 0;
            for (int i = 0; i < n; ++i) {
                if (assign[i] < 0) { free[i] = 1; ++nfree; }
                else free[i] = 0;
            }
        }
        ++phases;
        if (nfree > 0) {
            printf("  phase incomplete nfree=%d eps=%g\n", nfree, eps);
        }
        if (eps <= eps_final) break;
        eps *= factor;
        if (eps < eps_final) eps = eps_final;
        if (phases > 40) break;
    }
}

int main(int argc, char** argv) {
    int n = argc > 1 ? atoi(argv[1]) : 600;
    int threads = argc > 2 ? atoi(argv[2]) : 4;
    int seed = argc > 3 ? atoi(argv[3]) : 0;
    std::mt19937 rng(seed);
    std::uniform_real_distribution<double> ud(0, 1);
    std::vector<double> sp(n * 2), tp(n * 2);
    for (int i = 0; i < n * 2; ++i) { sp[i] = ud(rng); tp[i] = ud(rng); }
    std::vector<double> cost((long)n * n);
    for (int i = 0; i < n; ++i) {
        double sx = sp[2 * i], sy = sp[2 * i + 1];
        double* row = cost.data() + (long)i * n;
        for (int j = 0; j < n; ++j) {
            double dx = sx - tp[2 * j], dy = sy - tp[2 * j + 1];
            row[j] = std::sqrt(dx * dx + dy * dy);
        }
    }
    std::vector<int> assign(n);
    int phases = 0; long bids = 0;
    auto t0 = std::chrono::high_resolution_clock::now();
    auction_jacobi(n, cost.data(), assign.data(), threads, 1e-8, 0.25, phases, bids);
