#include <algorithm>
#include <chrono>
#include <cmath>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <immintrin.h>
#include <random>
#include <thread>
#include <vector>

// SIMD best+second over a row of values = -(cost + price) = -cost - price
// We track best and second values and best index.

struct Pair { double best, second; int best_j; };

Pair scan_scalar(const double* row, const double* price, int n) {
    int best_j = 0;
    double best = -(row[0] + price[0]);
    double second = -1e300;
    for (int j = 1; j < n; ++j) {
        double val = -(row[j] + price[j]);
        if (val > best) { second = best; best = val; best_j = j; }
        else if (val > second) second = val;
    }
    return {best, second, best_j};
}

// AVX scalar-fallback hybrid: process 4-wide, maintain 4 running bests then reduce.
// Second-best is trickier with SIMD; do a two-pass: SIMD argmax, then SIMD second excluding that index.
Pair scan_avx(const double* row, const double* price, int n) {
    __m256d bestv = _mm256_set1_pd(-1e300);
    __m256d besti = _mm256_setzero_pd();
    int j = 0;
    for (; j + 3 < n; j += 4) {
        __m256d c = _mm256_loadu_pd(row + j);
        __m256d p = _mm256_loadu_pd(price + j);
        __m256d val = _mm256_sub_pd(_mm256_setzero_pd(), _mm256_add_pd(c, p));
        __m256d idx = _mm256_set_pd(j + 3, j + 2, j + 1, j);
        __m256d mask = _mm256_cmp_pd(val, bestv, _CMP_GT_OQ);
        bestv = _mm256_blendv_pd(bestv, val, mask);
        besti = _mm256_blendv_pd(besti, idx, mask);
    }
    alignas(32) double bv[4], bi[4];
    _mm256_store_pd(bv, bestv);
    _mm256_store_pd(bi, besti);
    double best = bv[0]; int best_j = (int)bi[0];
    for (int k = 1; k < 4; ++k) if (bv[k] > best) { best = bv[k]; best_j = (int)bi[k]; }
    for (; j < n; ++j) {
        double val = -(row[j] + price[j]);
        if (val > best) { best = val; best_j = j; }
    }
    // second pass for second best, excluding best_j
    __m256d secv = _mm256_set1_pd(-1e300);
    j = 0;
    for (; j + 3 < n; j += 4) {
        __m256d c = _mm256_loadu_pd(row + j);
        __m256d p = _mm256_loadu_pd(price + j);
        __m256d val = _mm256_sub_pd(_mm256_setzero_pd(), _mm256_add_pd(c, p));
        // mask out best_j lane
        // if j..j+3 contains best_j, set that lane to -inf
        secv = _mm256_max_pd(secv, val);
    }
    alignas(32) double sv[4];
    _mm256_store_pd(sv, secv);
    double second = sv[0];
    for (int k = 1; k < 4; ++k) if (sv[k] > second) second = sv[k];
    for (; j < n; ++j) {
        double val = -(row[j] + price[j]);
        if (val > second) second = val;
    }
    // the SIMD second may equal best if best was in the max. Fix by rescanning the best's chunk scalarly? 
    // Simpler correct second: if second==best, recompute scalar second. Always exclude best_j explicitly.
    if (second >= best - 1e-15) {
        second = -1e300;
        for (int jj = 0; jj < n; ++jj) if (jj != best_j) {
            double val = -(row[jj] + price[jj]);
            if (val > second) second = val;
        }
    } else {
        // still might have included best_j if it wasn't the unique max in a way... 
        // max of all values equals best, so second from this pass is max of values that... 
        // WAIT: secv is max of ALL values including best, so second == best always.
        // This two-pass is wrong. Need to mask best_j.
    }
    // Correct masked second:
    second = -1e300;
    j = 0;
    for (; j + 3 < n; j += 4) {
        __m256d c = _mm256_loadu_pd(row + j);
        __m256d p = _mm256_loadu_pd(price + j);
        __m256d val = _mm256_sub_pd(_mm256_setzero_pd(), _mm256_add_pd(c, p));
        alignas(32) double tmp[4];
        _mm256_store_pd(tmp, val);
        for (int k = 0; k < 4; ++k) if (j + k != best_j && tmp[k] > second) second = tmp[k];
    }
    for (; j < n; ++j) if (j != best_j) {
        double val = -(row[j] + price[j]);
        if (val > second) second = val;
    }
    return {best, second, best_j};
}

// Parallel scan of one row across threads — overhead test
Pair scan_parallel(const double* row, const double* price, int n, int threads) {
    struct Local { double best, second; int best_j; };
    std::vector<Local> locs(threads);
    std::vector<std::thread> ts;
    int chunk = (n + threads - 1) / threads;
    for (int t = 0; t < threads; ++t) {
        int lo = t * chunk, hi = std::min(n, lo + chunk);
        ts.emplace_back([&, t, lo, hi]() {
            if (lo >= hi) { locs[t] = {-1e300, -1e300, -1}; return; }
            int bj = lo;
            double b = -(row[lo] + price[lo]);
            double s = -1e300;
            for (int j = lo + 1; j < hi; ++j) {
                double val = -(row[j] + price[j]);
                if (val > b) { s = b; b = val; bj = j; }
                else if (val > s) s = val;
            }
            locs[t] = {b, s, bj};
        });
    }
    for (auto& th : ts) th.join();
    double best = -1e300, second = -1e300; int best_j = -1;
    for (auto& L : locs) {
        if (L.best > best) { second = std::max(best, std::max(second, L.second)); best = L.best; best_j = L.best_j; }
        else { second = std::max(second, L.best); second = std::max(second, L.second); }
    }
    return {best, second, best_j};
}

int main() {
    int n = 600;
    std::mt19937 rng(0);
    std::uniform_real_distribution<double> ud(0, 1);
    std::vector<double> row(n), price(n);
    for (int i = 0; i < n; ++i) { row[i] = ud(rng); price[i] = ud(rng); }
    // correctness
    auto a = scan_scalar(row.data(), price.data(), n);
    auto b = scan_avx(row.data(), price.data(), n);
    printf("scalar best %g j %d second %g\n", a.best, a.best_j, a.second);
    printf("avx    best %g j %d second %g\n", b.best, b.best_j, b.second);
    auto c = scan_parallel(row.data(), price.data(), n, 4);
    printf("par    best %g j %d second %g\n", c.best, c.best_j, c.second);

    int reps = 20000;
    auto bench = [&](const char* name, auto fn) {
        auto t0 = std::chrono::high_resolution_clock::now();
        double sink = 0;
        for (int r = 0; r < reps; ++r) {
            auto p = fn();
            sink += p.best + p.second;
        }
        auto t1 = std::chrono::high_resolution_clock::now();
        printf("%s %.3f ms sink %g\n", name, std::chrono::duration<double, std::milli>(t1 - t0).count(), sink);
    };
    bench("scalar", [&]() { return scan_scalar(row.data(), price.data(), n); });
    bench("avx   ", [&]() { return scan_avx(row.data(), price.data(), n); });
    bench("par4  ", [&]() { return scan_parallel(row.data(), price.data(), n, 4); });
}
