static void auction_solve(int n, const double* cost, int* assign, double eps_final, double factor) {
    std::vector<double> price(n, 0.0);
    std::vector<int> owner(n, -1);
    double cmax = 0.0;
    for (long i = 0, N = (long)n * n; i < N; ++i) {
        double c = cost[i];
        if (c > cmax) cmax = c;
