        std::fill(assign, assign + n, -1);
        free_rows.clear();
        for (int i = n - 1; i >= 0; --i) free_rows.push_back(i);
        while (!free_rows.empty()) {
            int i = free_rows.back();
            free_rows.pop_back();
            const double* row = cost + (long)i * n;
            int best_j = 0;
            double best = -(row[0] + price[0]);
            double second = -1e300;
            for (int j = 1; j < n; ++j) {
                double val = -(row[j] + price[j]);
                if (val > best) {
                    second = best;
                    best = val;
                    best_j = j;
                } else if (val > second) {
                    second = val;
                }
            }
            price[best_j] += (best - second) + eps;
            int prev = owner[best_j];
            owner[best_j] = i;
            assign[i] = best_j;
            if (prev >= 0) free_rows.push_back(prev);
        }
        ++phases;
        if (eps <= eps_final) break;
        eps *= factor;
        if (eps < eps_final) eps = eps_final;
    }
}

static PyObject* solve_assign(PyObject* self, PyObject* args) {
    PyObject* cost_obj;
    double eps_final = 1e-9;
    double factor = 0.25;
    if (!PyArg_ParseTuple(args, "O|dd", &cost_obj, &eps_final, &factor)) return NULL;
    PyArrayObject* cost = (PyArrayObject*)PyArray_FROM_OTF(cost_obj, NPY_FLOAT64, NPY_ARRAY_IN_ARRAY);
    if (!cost) return NULL;
    if (PyArray_NDIM(cost) != 2) {
        Py_DECREF(cost);
        PyErr_SetString(PyExc_ValueError, "cost must be 2d");
        return NULL;
    }
    int n0 = (int)PyArray_DIM(cost, 0);
    int n1 = (int)PyArray_DIM(cost, 1);
    if (n0 != n1) {
        Py_DECREF(cost);
        PyErr_SetString(PyExc_ValueError, "cost must be square");
        return NULL;
    }
    const double* data = (const double*)PyArray_DATA(cost);
    // If not contiguous row-major with stride n, copy
    std::vector<double> tmp;
    const double* costp = data;
    if (!PyArray_IS_C_CONTIGUOUS(cost)) {
        tmp.resize((long)n0 * n1);
        for (int i = 0; i < n0; ++i) {
            for (int j = 0; j < n1; ++j) {
                tmp[(long)i * n1 + j] = *(double*)PyArray_GETPTR2(cost, i, j);
            }
        }
        costp = tmp.data();
    }
    std::vector<int> assign(n0);
    auction_solve(n0, costp, assign.data(), eps_final, factor);

    npy_intp dims[1] = {n0};
    PyObject* out = PyArray_SimpleNew(1, dims, NPY_INT32);
    if (!out) { Py_DECREF(cost); return NULL; }
    int32_t* o = (int32_t*)PyArray_DATA((PyArrayObject*)out);
    for (int i = 0; i < n0; ++i) o[i] = assign[i];
    Py_DECREF(cost);
    return out;
}

static PyMethodDef methods[] = {
    {"solve_assign", solve_assign, METH_VARARGS, "Auction assignment. Returns int32 column index per row."},
    {NULL, NULL, 0, NULL}
};

static struct PyModuleDef moduledef = {
    PyModuleDef_HEAD_INIT, "emdmod", NULL, -1, methods
};

PyMODINIT_FUNC PyInit_emdmod(void) {
    import_array();
    return PyModule_Create(&moduledef);
}
