#include <algorithm>
#include <chrono>
#include <cmath>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <numeric>
#include <random>
#include <vector>

// Sparse auction on a k-NN graph. NO outside edges.
// If the optimum lies in the k-NN graph this returns the exact assignment
// (for small enough epsilon), same as the dense auction restricted to those edges.

struct Result { bool ok; double ms; int phases; long iters; double cost; int bad; };

Result auction_knn(int n, int k, const int* nb, const double* nc, const double* full,
                   int* assign, double eps_final, double factor) {
    std::vector<double> price(n, 0.0);
    std::vector<int> owner(n, -1);
    double cmax = 0;
    for (long i = 0; i < (long)n * k; ++i) if (nc[i] > cmax) cmax = nc[i];
    double eps = cmax * 0.5 + 1e-15;
    std::vector<int> free_rows;
    free_rows.reserve(n * 4);
    int phases = 0; long iters = 0;
    auto t0 = std::chrono::high_resolution_clock::now();
    while (phases < 60) {
        std::fill(owner.begin(), owner.end(), -1);
        std::fill(assign, assign + n, -1);
        free_rows.clear();
        for (int i = n - 1; i >= 0; --i) free_rows.push_back(i);
        int guard = 0;
        const int GUARD = n * 500;
        while (!free_rows.empty()) {
            if (++guard > GUARD) {
                auto t1 = std::chrono::high_resolution_clock::now();
                return {false, std::chrono::duration<double,std::milli>(t1-t0).count(), phases, iters, 0, n};
            }
            int i = free_rows.back(); free_rows.pop_back();
            const int* cols = nb + (long)i * k;
            const double* cs = nc + (long)i * k;
            int best_j = cols[0];
            double best = -(cs[0] + price[cols[0]]);
            double second = -1e300;
            for (int t = 1; t < k; ++t) {
                int j = cols[t];
                double val = -(cs[t] + price[j]);
                if (val > best) { second = best; best = val; best_j = j; }
                else if (val > second) second = val;
            }
            // if all neighbors tie, second may still be -inf if k==1
            if (second < -1e200) second = best - 1.0;
            price[best_j] += (best - second) + eps;
            int prev = owner[best_j];
            owner[best_j] = i;
            assign[i] = best_j;
            ++iters;
            if (prev >= 0) free_rows.push_back(prev);
        }
        ++phases;
        if (eps <= eps_final) break;
        eps *= factor;
        if (eps < eps_final) eps = eps_final;
    }
    auto t1 = std::chrono::high_resolution_clock::now();
    double s = 0; int bad = 0;
    std::vector<char> used(n, 0);
    for (int i = 0; i < n; ++i) {
        int j = assign[i];
        if (j < 0 || j >= n || used[j]) bad++;
        else { used[j] = 1; s += full[(long)i * n + j]; }
    }
    return {bad == 0, std::chrono::duration<double,std::milli>(t1-t0).count(), phases, iters, s, bad};
}

int main(int argc, char** argv) {
    int n = atoi(argv[1]);
    int k = atoi(argv[2]);
    int seed = atoi(argv[3]);
    int ns = argc > 4 ? atoi(argv[4]) : 1;
    for (int sidx = 0; sidx < ns; ++sidx) {
        std::mt19937 rng(seed + sidx);
        std::uniform_real_distribution<double> ud(0, 1);
        std::vector<double> sp(n * 2), tp(n * 2);
        for (int i = 0; i < n * 2; ++i) { sp[i] = ud(rng); tp[i] = ud(rng); }
        std::vector<double> cost((long)n * n);
        auto tA = std::chrono::high_resolution_clock::now();
        for (int i = 0; i < n; ++i) {
            double sx = sp[2 * i], sy = sp[2 * i + 1];
            double* row = cost.data() + (long)i * n;
            for (int j = 0; j < n; ++j) {
                double dx = sx - tp[2 * j], dy = sy - tp[2 * j + 1];
                row[j] = std::sqrt(dx * dx + dy * dy);
            }
        }
        std::vector<int> nb((long)n * k);
        std::vector<double> nc((long)n * k);
        std::vector<int> idx(n);
        for (int i = 0; i < n; ++i) {
            std::iota(idx.begin(), idx.end(), 0);
            const double* row = cost.data() + (long)i * n;
            std::nth_element(idx.begin(), idx.begin() + (k - 1), idx.end(),
                             [&](int a, int b) { return row[a] < row[b]; });
            for (int t = 0; t < k; ++t) {
                nb[(long)i * k + t] = idx[t];
                nc[(long)i * k + t] = row[idx[t]];
            }
        }
        auto tB = std::chrono::high_resolution_clock::now();
        std::vector<int> assign(n);
        Result r = auction_knn(n, k, nb.data(), nc.data(), cost.data(), assign.data(), 1e-9, 0.25);
        auto tC = std::chrono::high_resolution_clock::now();
        double build = std::chrono::duration<double,std::milli>(tB - tA).count();
        double all = std::chrono::duration<double,std::milli>(tC - tA).count();
        printf("seed=%d ok=%d bad=%d phases=%d iters=%ld build=%.2f solve=%.2f all=%.2f cost=%.6f\n",
               seed + sidx, (int)r.ok, r.bad, r.phases, r.iters, build, r.ms, all, r.cost);
        if (sidx == 0) {
            FILE* f = fopen("build/as.txt", "w"); fprintf(f, "%d\n", n);
            for (int i = 0; i < n; ++i) fprintf(f, "%d\n", assign[i]); fclose(f);
            FILE* fc = fopen("build/cost.bin", "wb"); fwrite(cost.data(), 8, (long)n * n, fc); fclose(fc);
        }
    }
}
