#include <algorithm>
#include <chrono>
#include <cmath>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <numeric>
#include <random>
#include <vector>

// Adaptive sparse auction.
// Round 1: kNN candidates.
// Then add all negative reduced-cost edges (using auction prices as duals) and re-solve,
// warm-starting prices. Repeat until no violations.
//
// Dual interpretation: person i's profit is -cost - price, and the bid makes the
// winning column's price rise. At convergence with tiny eps, price[j] approximates
// the dual v[j], and the matched reduced costs are ~0. A missing edge (i,j) violates
// optimality if cost[i,j] + price[j] < cost[i, match[i]] + price[match[i]] - tol
// i.e. if its value beats the matched value.

struct Result { bool ok; double ms; int rounds; int phases; long iters; int added; double min_slack; };

Result solve(int n, int k0, const double* cost, int* assign, double eps_final) {
    std::vector<std::vector<int>> nb(n);
    std::vector<std::vector<double>> nc(n);
    std::vector<uint8_t> has((long)n * n, 0);
    std::vector<int> idx(n);
    for (int i = 0; i < n; ++i) {
        std::iota(idx.begin(), idx.end(), 0);
        const double* row = cost + (long)i * n;
        std::nth_element(idx.begin(), idx.begin() + (k0 - 1), idx.end(),
