                assign[i] = best_j;
                ++iters;
                if (prev >= 0) free_rows.push_back(prev);
            }
            if (!ok) break;
            ++phases; ++phases_total;
            if (eps <= eps_final) break;
            eps *= 0.25;
            if (eps < eps_final) eps = eps_final;
        }
        if (!ok) break;
        ++rounds;

        // pricing: find edges better than the current assignment by more than tol
        int added = 0;
        min_slack = 1e300;
        for (int i = 0; i < n; ++i) {
            const double* row = cost + (long)i * n;
            int jm = assign[i];
            double matched_val = -(row[jm] + price[jm]);
            uint8_t* h = has.data() + (long)i * n;
            for (int j = 0; j < n; ++j) {
                double val = -(row[j] + price[j]);
                double slack = matched_val - val; // positive if matched is better
                if (slack < min_slack) min_slack = slack;
                if (slack < -1e-8 && !h[j]) {
                    h[j] = 1;
                    nb[i].push_back(j);
                    nc[i].push_back(row[j]);
                    ++added;
                }
            }
        }
        added_total += added;
        if (added == 0) break;
    }
    auto t1 = std::chrono::high_resolution_clock::now();
    return {ok, std::chrono::duration<double,std::milli>(t1-t0).count(), rounds, phases_total, iters, added_total, min_slack};
}

int main(int argc, char** argv) {
    int n = atoi(argv[1]), k0 = atoi(argv[2]), seed0 = atoi(argv[3]), ns = atoi(argv[4]);
    double sum = 0;
    for (int sidx = 0; sidx < ns; ++sidx) {
        std::mt19937 rng(seed0 + sidx);
        std::uniform_real_distribution<double> ud(0, 1);
        std::vector<double> sp(n * 2), tp(n * 2);
        for (int i = 0; i < n * 2; ++i) { sp[i] = ud(rng); tp[i] = ud(rng); }
        auto tA = std::chrono::high_resolution_clock::now();
        std::vector<double> cost((long)n * n);
        for (int i = 0; i < n; ++i) {
            double sx = sp[2 * i], sy = sp[2 * i + 1];
            double* row = cost.data() + (long)i * n;
            for (int j = 0; j < n; ++j) {
                double dx = sx - tp[2 * j], dy = sy - tp[2 * j + 1];
                row[j] = std::sqrt(dx * dx + dy * dy);
            }
        }
        std::vector<int> assign(n);
        Result r = solve(n, k0, cost.data(), assign.data(), 1e-9);
        auto tB = std::chrono::high_resolution_clock::now();
        double all = std::chrono::duration<double,std::milli>(tB - tA).count();
        sum += all;
        double s = 0; int bad = 0; std::vector<char> used(n, 0);
        for (int i = 0; i < n; ++i) {
            int j = assign[i];
            if (j < 0 || j >= n || used[j]) bad++;
            else { used[j] = 1; s += cost[(long)i * n + j]; }
        }
        printf("seed=%d ok=%d bad=%d rounds=%d phases=%d iters=%ld added=%d solve=%.2f all=%.2f slack=%.2e cost=%.6f\n",
               seed0 + sidx, (int)r.ok, bad, r.rounds, r.phases, r.iters, r.added, r.ms, all, r.min_slack, s);
        if (sidx == 0) {
            FILE* f = fopen("build/as.txt", "w"); fprintf(f, "%d\n", n);
            for (int i = 0; i < n; ++i) fprintf(f, "%d\n", assign[i]); fclose(f);
            FILE* fc = fopen("build/cost.bin", "wb"); fwrite(cost.data(), 8, (long)n * n, fc); fclose(fc);
        }
    }
    printf("AVG all %.2f\n", sum / ns);
}
