            std::nth_element(idx.begin(), idx.begin() + (k0 - 1), idx.end(),
                             [&](int a, int b) { return row[a] < row[b]; });
            nb[i].reserve(k0 + 64); nc[i].reserve(k0 + 64);
            for (int t = 0; t < k0; ++t) {
                int j = idx[t];
                nb[i].push_back(j); nc[i].push_back(row[j]);
                has[(long)i * n + j] = 1;
            }
        }

        std::vector<double> price(n, 0.0);
        std::vector<int> owner(n, -1), assign(n, -1);
        std::vector<int> free_rows; free_rows.reserve(n * 4);
        std::vector<char> touched(n, 1);

        auto run_bids = [&](double eps, const std::vector<int>& seeds) -> bool {
            free_rows.clear();
            for (int i : seeds) {
                int j = assign[i];
                if (j >= 0) { owner[j] = -1; assign[i] = -1; }
                free_rows.push_back(i);
            }
            int guard = 0;
            while (!free_rows.empty()) {
                if (++guard > n * 800) return false;
                int i = free_rows.back(); free_rows.pop_back();
                const auto& cols = nb[i]; const auto& cs = nc[i];
                int deg = (int)cols.size();
                int best_j = cols[0];
                double best = -(cs[0] + price[cols[0]]);
                double second = -1e300;
                for (int t = 1; t < deg; ++t) {
                    int j = cols[t];
                    double val = -(cs[t] + price[j]);
                    if (val > best) { second = best; best = val; best_j = j; }
                    else if (val > second) second = val;
                }
                if (second < -1e200) second = best - 1.0;
                price[best_j] += (best - second) + eps;
                int prev = owner[best_j];
                owner[best_j] = i;
                assign[i] = best_j;
                if (prev >= 0) free_rows.push_back(prev);
            }
