                uint8_t* h = has.data() + (long)i * n;
                bool d = false;
                for (int j = 0; j < n; ++j) {
                    double val = -(row[j] + price[j]);
                    double slack = matched_val - val;
                    if (slack < min_slack) min_slack = slack;
                    if (slack < -1e-8 && !h[j]) {
                        h[j] = 1; nb[i].push_back(j); nc[i].push_back(row[j]); ++added; d = true;
                    }
                }
