#include <algorithm>
#include <chrono>
#include <cmath>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <numeric>
#include <random>
#include <vector>

// CSR-based sparse JV, no per-iteration heap allocations, warm duals.
// Pricing adds violators. Linear active-set min.

struct Result { bool ok; double ms; int rounds; long scans; int added; double minrc; };

Result solve(int n, int k0, const double* cost, int* match_col) {
    const double INF = 1e100;
    // neighbor storage: start with k0, grow by appending into a big pool? 
    // per-row vectors cause alloc. Use a single CSR rebuilt only when edges are added,
    // and the solver reads CSR.
    std::vector<int> nb;
    std::vector<double> nc;
    nb.reserve((long)n * (k0 + 16));
    nc.reserve((long)n * (k0 + 16));
    std::vector<int> off(n + 1);
    std::vector<uint8_t> has((long)n * n, 0);

    std::vector<int> idx(n);
    off[0] = 0;
    for (int i = 0; i < n; ++i) {
        std::iota(idx.begin(), idx.end(), 0);
        const double* row = cost + (long)i * n;
        std::nth_element(idx.begin(), idx.begin() + (k0 - 1), idx.end(),
                         [&](int a, int b) { return row[a] < row[b]; });
        for (int t = 0; t < k0; ++t) {
            int j = idx[t];
            nb.push_back(j);
            nc.push_back(row[j]);
            has[(long)i * n + j] = 1;
        }
        off[i + 1] = (int)nb.size();
    }

    std::vector<double> u(n), v(n, 0.0);
    std::vector<int> row_of_col(n, -1), prev_col(n, -1);
    std::vector<double> dist(n);
    std::vector<int> pred(n), seen(n, 0);
    std::vector<int> active; active.reserve(4096);
    std::vector<int> scanned; scanned.reserve(1024);
    int stamp_gen = 1;

    for (int i = 0; i < n; ++i) {
        double m = INF;
        for (int p = off[i]; p < off[i + 1]; ++p) if (nc[p] < m) m = nc[p];
        u[i] = m;
    }

    auto augment_all = [&]() -> bool {
        std::fill(row_of_col.begin(), row_of_col.end(), -1);
        std::fill(prev_col.begin(), prev_col.end(), -1);
        for (int i = 0; i < n; ++i) {
            if (stamp_gen > 1000000000) { std::fill(seen.begin(), seen.end(), 0); stamp_gen = 1; }
            int my = stamp_gen++;
            active.clear(); scanned.clear();
            double ui = u[i];
            for (int p = off[i]; p < off[i + 1]; ++p) {
                int j = nb[p];
                dist[j] = nc[p] - ui - v[j];
                pred[j] = i; seen[j] = my; active.push_back(j);
            }
            int free_col = -1; double delta = 0;
            while (true) {
                int na = (int)active.size();
                if (!na) return false;
                int best_p = 0; double dmin = dist[active[0]];
                for (int p = 1; p < na; ++p) {
                    double d = dist[active[p]];
                    if (d < dmin) { dmin = d; best_p = p; }
                }
                int jmin = active[best_p];
                active[best_p] = active[--na]; active.pop_back();
                scanned.push_back(jmin); seen[jmin] = -my;
                int r = row_of_col[jmin];
                if (r < 0) { free_col = jmin; delta = dmin; break; }
                double base = dmin - u[r];
                for (int p = off[r]; p < off[r + 1]; ++p) {
                    int j = nb[p]; int st = seen[j];
                    if (st == -my) continue;
                    double cand = base + nc[p] - v[j];
                    if (st != my) { dist[j] = cand; pred[j] = r; seen[j] = my; active.push_back(j); }
                    else if (cand < dist[j]) { dist[j] = cand; pred[j] = r; }
                }
            }
            int ns = (int)scanned.size();
            for (int s = 0; s < ns; ++s) v[scanned[s]] += dist[scanned[s]] - delta;
            u[i] += delta;
            for (int s = 0; s < ns; ++s) {
                int j = scanned[s];
                int r = row_of_col[j];
                if (r >= 0) u[r] += delta - dist[j];
            }
            int j = free_col;
            while (true) {
                int r = pred[j]; int pj = prev_col[r];
                row_of_col[j] = r; prev_col[r] = j;
                if (r == i) break; j = pj;
            }
        }
        return true;
    };

    auto t0 = std::chrono::high_resolution_clock::now();
    int rounds = 0; int added_total = 0; double minrc = 0; bool ok = true;
    // extra edges collected then appended by rebuilding off — we'll append in place
    // by storing new edges in side buffers and compacting.
    std::vector<int> extra_j; std::vector<double> extra_c; std::vector<int> extra_row;
    while (rounds < 12) {
        if (!augment_all()) { ok = false; break; }
        ++rounds;
        extra_j.clear(); extra_c.clear(); extra_row.clear();
        minrc = 1e300;
        for (int i = 0; i < n; ++i) {
            const double* row = cost + (long)i * n;
            double ui = u[i];
            uint8_t* h = has.data() + (long)i * n;
            for (int j = 0; j < n; ++j) {
                double rc = row[j] - ui - v[j];
                if (rc < minrc) minrc = rc;
                if (rc < -1e-8 && !h[j]) {
                    h[j] = 1;
                    extra_row.push_back(i);
                    extra_j.push_back(j);
                    extra_c.push_back(row[j]);
                }
            }
        }
        int added = (int)extra_j.size();
        added_total += added;
        if (!added) break;
        // rebuild CSR with extras. Count new degrees.
        std::vector<int> add_count(n, 0);
        for (int i : extra_row) add_count[i]++;
        std::vector<int> new_off(n + 1);
        new_off[0] = 0;
        for (int i = 0; i < n; ++i) new_off[i + 1] = new_off[i] + (off[i + 1] - off[i]) + add_count[i];
        std::vector<int> new_nb(new_off[n]);
        std::vector<double> new_nc(new_off[n]);
        std::vector<int> cursor = new_off;
        for (int i = 0; i < n; ++i) {
            for (int p = off[i]; p < off[i + 1]; ++p) {
                new_nb[cursor[i]] = nb[p];
                new_nc[cursor[i]] = nc[p];
                cursor[i]++;
            }
        }
        for (int t = 0; t < added; ++t) {
            int i = extra_row[t];
            new_nb[cursor[i]] = extra_j[t];
            new_nc[cursor[i]] = extra_c[t];
            cursor[i]++;
        }
        nb.swap(new_nb); nc.swap(new_nc); off.swap(new_off);
    }
    if (ok) for (int j = 0; j < n; ++j) match_col[row_of_col[j]] = j;
    auto t1 = std::chrono::high_resolution_clock::now();
    return {ok, std::chrono::duration<double,std::milli>(t1 - t0).count(), rounds, 0, added_total, minrc};
}

int main(int argc, char** argv) {
    int n = atoi(argv[1]), k0 = atoi(argv[2]), seed0 = atoi(argv[3]), ns = atoi(argv[4]);
    double sum = 0;
    for (int sidx = 0; sidx < ns; ++sidx) {
        std::mt19937 rng(seed0 + sidx);
        std::uniform_real_distribution<double> ud(0, 1);
        std::vector<double> sp(n * 2), tp(n * 2);
        for (int i = 0; i < n * 2; ++i) { sp[i] = ud(rng); tp[i] = ud(rng); }
        auto tA = std::chrono::high_resolution_clock::now();
        std::vector<double> cost((long)n * n);
        for (int i = 0; i < n; ++i) {
            double sx = sp[2 * i], sy = sp[2 * i + 1];
            double* row = cost.data() + (long)i * n;
            for (int j = 0; j < n; ++j) {
                double dx = sx - tp[2 * j], dy = sy - tp[2 * j + 1];
                row[j] = std::sqrt(dx * dx + dy * dy);
            }
        }
        std::vector<int> match(n);
        Result r = solve(n, k0, cost.data(), match.data());
        auto tB = std::chrono::high_resolution_clock::now();
        double all = std::chrono::duration<double,std::milli>(tB - tA).count();
        sum += all;
        double s = 0; int bad = 0; std::vector<char> used(n, 0);
        if (r.ok) for (int i = 0; i < n; ++i) {
            int j = match[i];
            if (j < 0 || j >= n || used[j]) bad++;
            else { used[j] = 1; s += cost[(long)i * n + j]; }
        }
        printf("seed=%d ok=%d bad=%d rounds=%d added=%d solve=%.2f all=%.2f minrc=%.1e cost=%.6f\n",
               seed0 + sidx, (int)r.ok, bad, r.rounds, r.added, r.ms, all, r.minrc, s);
        if (sidx == 0) {
            FILE* f = fopen("build/as.txt","w"); fprintf(f,"%d\n", n);
            for (int i = 0; i < n; ++i) fprintf(f, "%d\n", match[i]); fclose(f);
            FILE* fc = fopen("build/cost.bin","wb"); fwrite(cost.data(), 8, (long)n*n, fc); fclose(fc);
        }
    }
    printf("AVG all %.2f\n", sum / ns);
}
