#include <chrono>
#include <cmath>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <numeric>
#include <random>
#include <vector>

// Auction for a few coarse phases, then one JV refinement on the full graph
// but only for rows whose matched edge is not complementary-slack with the
// auction prices... Actually after coarse auction the assignment may already
// be optimal. We check reduced-cost optimality of the FULL matrix using
// auction prices as duals v, and u[i] = cost[i, match[i]] + v[match[i]]
// (so matched reduced cost is 0). Violation: cost[i,j] - u[i] - v[j] < -tol.
// If any violation, we fall back to a full dense JV (slow) — we want this rare.
// First just MEASURE how often coarse auction is already optimal and the cost gap.

int main(int argc, char** argv) {
    int n = 600;
    int stop_phase = argc > 1 ? atoi(argv[1]) : 8;
    int ns = argc > 2 ? atoi(argv[2]) : 8;
    for (int seed = 0; seed < ns; ++seed) {
        std::mt19937 rng(seed);
        std::uniform_real_distribution<double> ud(0, 1);
        std::vector<double> sp(n * 2), tp(n * 2);
        for (int i = 0; i < n * 2; ++i) { sp[i] = ud(rng); tp[i] = ud(rng); }
        std::vector<double> cost((long)n * n);
        for (int i = 0; i < n; ++i) {
            double sx = sp[2 * i], sy = sp[2 * i + 1];
            double* row = cost.data() + (long)i * n;
            for (int j = 0; j < n; ++j) {
                double dx = sx - tp[2 * j], dy = sy - tp[2 * j + 1];
                row[j] = std::sqrt(dx * dx + dy * dy);
            }
        }
        std::vector<double> price(n, 0.0);
        std::vector<int> owner(n, -1), assign(n, -1), free_rows;
        free_rows.reserve(n * 4);
        double cmax = 0;
        for (double c : cost) if (c > cmax) cmax = c;
        double eps = cmax * 0.5;
        auto t0 = std::chrono::high_resolution_clock::now();
        for (int phase = 0; phase < stop_phase; ++phase) {
            std::fill(owner.begin(), owner.end(), -1);
            std::fill(assign.begin(), assign.end(), -1);
            free_rows.clear();
            for (int i = n - 1; i >= 0; --i) free_rows.push_back(i);
            while (!free_rows.empty()) {
                int i = free_rows.back(); free_rows.pop_back();
                const double* row = cost.data() + (long)i * n;
                int best_j = 0;
                double best = -(row[0] + price[0]);
                double second = -1e300;
                for (int j = 1; j < n; ++j) {
                    double val = -(row[j] + price[j]);
                    if (val > best) { second = best; best = val; best_j = j; }
                    else if (val > second) second = val;
                }
                price[best_j] += best - second + eps;
                int prev = owner[best_j];
                owner[best_j] = i;
                assign[i] = best_j;
                if (prev >= 0) free_rows.push_back(prev);
            }
            eps *= 0.25;
        }
        auto t1 = std::chrono::high_resolution_clock::now();
        // reduced cost check
        double minrc = 1e300;
        int viol = 0;
        for (int i = 0; i < n; ++i) {
            const double* row = cost.data() + (long)i * n;
            int jm = assign[i];
            double ui = row[jm] + price[jm];
            for (int j = 0; j < n; ++j) {
                double rc = row[j] - ui + price[j]; // v = -price? 
                // matched value uses price as the column price added to cost.
                // optimality of assignment for min cost+price: 
                // cost[i,j] + price[j] >= cost[i, match] + price[match] for all j
                // rc = cost[i,j] + price[j] - cost[i,match] - price[match] >= 0
                rc = row[j] + price[j] - row[jm] - price[jm];
                if (rc < minrc) minrc = rc;
                if (rc < -1e-8) viol++;
            }
        }
        double ms = std::chrono::duration<double, std::milli>(t1 - t0).count();
        double s = 0;
        for (int i = 0; i < n; ++i) s += cost[(long)i * n + assign[i]];
        printf("seed=%d phases=%d time=%.2f ms cost=%.6f minrc=%.3e viol_edges=%d\n",
               seed, stop_phase, ms, s, minrc, viol);
        if (seed == 0) {
            FILE* f = fopen("build/as.txt", "w"); fprintf(f, "%d\n", n);
            for (int i = 0; i < n; ++i) fprintf(f, "%d\n", assign[i]); fclose(f);
            FILE* fc = fopen("build/cost.bin", "wb"); fwrite(cost.data(), 8, (long)n * n, fc); fclose(fc);
        }
    }
}
