{"command":"cat > ./build/inner.cpp << 'EOF'
#include <algorithm>
#include <chrono>
#include <cmath>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <numeric>
#include <random>
#include <vector>

// Tight sparse shortest-path assignment. All storage is raw arrays.
// Reports time of augmentations only.

int main(int argc, char** argv) {
    int n = 600;
    int k = argc > 1 ? atoi(argv[1]) : 32;
    int seed = argc > 2 ? atoi(argv[2]) : 0;
    std::mt19937 rng(seed);
    std::uniform_real_distribution<double> ud(0, 1);
    std::vector<double> cost((long)n * n);
    // geometric costs
    std::vector<double> sp(n * 2), tp(n * 2);
    for (int i = 0; i < n * 2; ++i) { sp[i] = ud(rng); tp[i] = ud(rng); }
    for (int i = 0; i < n; ++i) {
        double sx = sp[2 * i], sy = sp[2 * i + 1];
        double* row = cost.data() + (long)i * n;
        for (int j = 0; j < n; ++j) {
            double dx = sx - tp[2 * j], dy = sy - tp[2 * j + 1];
            row[j] = std::sqrt(dx * dx + dy * dy);
        }
    }
    std::vector<int> nb((long)n * k);
    std::vector<double> nc((long)n * k);
    std::vector<int> idx(n);
    for (int i = 0; i < n; ++i) {
        std::iota(idx.begin(), idx.end(), 0);
        const double* row = cost.data() + (long)i * n;
        std::nth_element(idx.begin(), idx.begin() + k - 1, idx.end(),
                         [&](int a, int b) { return row[a] < row[b]; });
        for (int t = 0; t < k; ++t) {
            nb[(long)i * k + t] = idx[t];
            nc[(long)i * k + t] = row[idx[t]];
        }
    }

    std::vector<double> u(n), v(n, 0.0);
    for (int i = 0; i < n; ++i) {
        double m = 1e100;
        for (int t = 0; t < k; ++t) m = std::min(m, nc[(long)i * k + t]);
        u[i] = m;
    }
    std::vector<int> row_of_col(n, -1), prev_col(n, -1);
    std::vector<double> dist(n);
    std::vector<int> pred(n);
    std::vector<int> seen(n, 0);
    // fixed active buffer
    std::vector<int> active(n);
    std::vector<int> scanned(n);
    int stamp = 1;

    auto t0 = std::chrono::high_resolution_clock::now();
    long scans = 0, relaxes = 0;
    for (int i = 0; i < n; ++i) {
        int my = stamp++;
        int nactive = 0;
        int nscanned = 0;
        double ui = u[i];
        const int* cols = nb.data() + (long)i * k;
        const double* cs = nc.data() + (long)i * k;
        for (int t = 0; t < k; ++t) {
            int j = cols[t];
            dist[j] = cs[t] - ui - v[j];
            pred[j] = i;
            seen[j] = my;
            active[nactive++] = j;
        }
        int free_col = -1;
        double delta = 0;
        while (nactive) {
            int best_p = 0;
            double dmin = dist[active[0]];
            for (int p = 1; p < nactive; ++p) {
                double d = dist[active[p]];
                if (d < dmin) { dmin = d; best_p = p; }
            }
            int jmin = active[best_p];
            active[best_p] = active[--nactive];
            scanned[nscanned++] = jmin;
            seen[jmin] = -my;
            ++scans;
            int r = row_of_col[jmin];
            if (r < 0) { free_col = jmin; delta = dmin; break; }
            const int* rcols = nb.data() + (long)r * k;
            const double* rcs = nc.data() + (long)r * k;
            double base = dmin - u[r];
            for (int t = 0; t < k; ++t) {
                int j = rcols[t];
                int st = seen[j];
                if (st == -my) continue;
                double cand = base + rcs[t] - v[j];
                ++relaxes;
                if (st != my) {
                    dist[j] = cand; pred[j] = r; seen[j] = my; active[nactive++] = j;
                } else if (cand < dist[j]) {
                    dist[j] = cand; pred[j] = r;
                }
            }
        }
        if (free_col < 0) { printf("FAIL at row %d\n", i); return 1; }
        for (int s = 0; s < nscanned; ++s) v[scanned[s]] += dist[scanned[s]] - delta;
        u[i] += delta;
        for (int s = 0; s < nscanned; ++s) {
            int j = scanned[s];
            int r = row_of_col[j];
            if (r >= 0) u[r] += delta - dist[j];
        }
        int j = free_col;
        while (true) {
            int r = pred[j];
            int pj = prev_col[r];
            row_of_col[j] = r;
            prev_col[r] = j;
            if (r == i) break;
            j = pj;
        }
    }
    auto t1 = std::chrono::high_resolution_clock::now();
    double ms = std::chrono::duration<double, std::milli>(t1 - t0).count();
    double s = 0;
    std::vector<int> col(n);
    for (int j = 0; j < n; ++j) col[row_of_col[j]] = j;
    for (int i = 0; i < n; ++i) s += cost[(long)i * n + col[i]];
    printf("k=%d time=%.3f ms scans=%ld relaxes=%ld cost=%.6f\n", k, ms, scans, relaxes, s);
    return 0;
}
