#include <algorithm>
#include <chrono>
#include <cmath>
#include <cstdio>
#include <cstdint>
#include <numeric>
#include <random>
#include <thread>
#include <vector>

// Time one shortest-path augmentation (dense, scanning all columns) vs
// running B of them in parallel on independent dual snapshots.
// This measures whether the inner loop parallelizes across augmentations.

void one_aug(int n, const double* cost, const double* u, const double* v,
             const int* row_of_col, int start_row, int& scans) {
    std::vector<double> dist(n);
    std::vector<char> scanned(n, 0);
    const double* row = cost + (long)start_row * n;
    double ui = u[start_row];
    for (int j = 0; j < n; ++j) dist[j] = row[j] - ui - v[j];
    int nscan = 0;
    while (true) {
        double dmin = 1e100; int jmin = -1;
        for (int j = 0; j < n; ++j) if (!scanned[j] && dist[j] < dmin) { dmin = dist[j]; jmin = j; }
        scanned[jmin] = 1; ++nscan;
        int r = row_of_col[jmin];
        if (r < 0 || nscan > 80) break; // stop early like typical tree size
        const double* rrow = cost + (long)r * n;
        double base = dmin - u[r];
        for (int j = 0; j < n; ++j) {
            if (scanned[j]) continue;
            double cand = base + rrow[j] - v[j];
            if (cand < dist[j]) dist[j] = cand;
        }
    }
    scans = nscan;
}

int main() {
    int n = 600;
    std::mt19937 rng(0);
    std::uniform_real_distribution<double> ud(0, 1);
    std::vector<double> cost((long)n * n), u(n), v(n);
    for (int i = 0; i < n; ++i) {
        u[i] = ud(rng); v[i] = ud(rng);
        for (int j = 0; j < n; ++j) cost[(long)i * n + j] = ud(rng);
    }
    std::vector<int> row_of_col(n);
    std::iota(row_of_col.begin(), row_of_col.end(), 0);
    // a few free
    for (int j = 0; j < 30; ++j) row_of_col[j] = -1;

    auto bench = [&](int threads, int reps) {
        auto t0 = std::chrono::high_resolution_clock::now();
        if (threads == 1) {
            int scans = 0;
            for (int r = 0; r < reps; ++r) one_aug(n, cost.data(), u.data(), v.data(), row_of_col.data(), r % n, scans);
        } else {
            int done = 0;
            while (done < reps) {
                int batch = std::min(threads, reps - done);
                std::vector<std::thread> ts;
                std::vector<int> scans(batch);
                for (int t = 0; t < batch; ++t) {
                    int row = (done + t) % n;
                    ts.emplace_back([&, t, row]() {
                        one_aug(n, cost.data(), u.data(), v.data(), row_of_col.data(), row, scans[t]);
                    });
                }
                for (auto& th : ts) th.join();
                done += batch;
            }
        }
        auto t1 = std::chrono::high_resolution_clock::now();
        double ms = std::chrono::duration<double, std::milli>(t1 - t0).count();
        printf("threads=%d reps=%d total=%.2f ms per_aug=%.3f ms\n", threads, reps, ms, ms / reps);
    };
    for (int th : {1, 2, 4, 6}) bench(th, 48);
}
