#include <algorithm>
#include <chrono>
#include <cmath>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <random>
#include <vector>

// Compare row-major scan vs blocked (tile) scan for best/second.
// Blocked: cost stored as tiles of B columns so a row's values for a tile
// are contiguous AND we can keep prices hot... prices are 1d so row-major
// already streams cost+price sequentially. Blocking won't help a single row scan.
// Instead try software prefetch and also unrolling.
// And try scanning cost in float while price is double? 

int main() {
    int n = 600;
    int reps = 30000;
    std::vector<double> row(n), price(n);
    std::mt19937 rng(0);
    std::uniform_real_distribution<double> ud(0,1);
    for (int i = 0; i < n; ++i) { row[i] = ud(rng); price[i] = ud(rng); }

    auto t0 = std::chrono::high_resolution_clock::now();
    double sink = 0;
    for (int r = 0; r < reps; ++r) {
        int best_j = 0;
        double best = -(row[0] + price[0]);
        double second = -1e300;
        #pragma unroll 4
        for (int j = 1; j < n; ++j) {
            double val = -(row[j] + price[j]);
            if (val > best) { second = best; best = val; best_j = j; }
            else if (val > second) second = val;
        }
        sink += best + second + best_j;
        // perturb so compiler can't hoist
        price[r % n] += 1e-18;
    }
    auto t1 = std::chrono::high_resolution_clock::now();
    double ms = std::chrono::duration<double, std::milli>(t1 - t0).count();
    printf("scalar reps=%d total=%.2f ms per_scan=%.4f us sink=%g\n", reps, ms, ms * 1000 / reps, sink);
    printf("implied bandwidth %.2f GB/s\n", (reps * (double)n * 16) / (ms / 1000) / 1e9);
}
