#include <algorithm>
#include <chrono>
#include <cmath>
#include <cstdint>
#include <cstdio>
#include <numeric>
#include <random>
#include <thread>
#include <vector>

// Parallelize independent sparse shortest-path searches (read-only graph and duals).
// Each search stops after `limit` scans, matching typical tree size, and writes a sink
// so the compiler cannot delete the work.

struct Graph {
    int n, k;
    const int* nb;
    const double* nc;
};

int search(const Graph& g, const double* u, const double* v, const int* row_of_col,
           int start, int limit) {
    int n = g.n, k = g.k;
    std::vector<double> dist(n, 1e100);
    std::vector<int> seen(n, 0);
    std::vector<int> active(n);
    int nactive = 0;
    const int* cols = g.nb + (long)start * k;
    const double* cs = g.nc + (long)start * k;
    double ui = u[start];
    for (int t = 0; t < k; ++t) {
        int j = cols[t];
        dist[j] = cs[t] - ui - v[j];
        seen[j] = 1;
        active[nactive++] = j;
    }
    int nscan = 0;
    double last = 0;
    while (nactive && nscan < limit) {
        int best_p = 0;
        double dmin = dist[active[0]];
        for (int p = 1; p < nactive; ++p) {
            double d = dist[active[p]];
            if (d < dmin) { dmin = d; best_p = p; }
        }
        int jmin = active[best_p];
        active[best_p] = active[--nactive];
        seen[jmin] = 2;
        ++nscan;
        last = dmin;
        int r = row_of_col[jmin];
        if (r < 0) break;
        const int* rcols = g.nb + (long)r * k;
        const double* rcs = g.nc + (long)r * k;
        double base = dmin - u[r];
        for (int t = 0; t < k; ++t) {
            int j = rcols[t];
            int st = seen[j];
            if (st == 2) continue;
            double cand = base + rcs[t] - v[j];
            if (st == 0) {
                dist[j] = cand; seen[j] = 1; active[nactive++] = j;
            } else if (cand < dist[j]) {
                dist[j] = cand;
            }
        }
    }
    return nscan + (int)(last * 1e6);
}

int main() {
    int n = 600, k = 32, limit = 40;
    std::mt19937 rng(0);
    std::uniform_real_distribution<double> ud(0, 1);
    std::vector<double> sp(n * 2), tp(n * 2);
    for (int i = 0; i < n * 2; ++i) { sp[i] = ud(rng); tp[i] = ud(rng); }
    std::vector<double> cost((long)n * n);
    for (int i = 0; i < n; ++i) {
        double sx = sp[2 * i], sy = sp[2 * i + 1];
        double* row = cost.data() + (long)i * n;
        for (int j = 0; j < n; ++j) {
            double dx = sx - tp[2 * j], dy = sy - tp[2 * j + 1];
            row[j] = std::sqrt(dx * dx + dy * dy);
        }
    }
    std::vector<int> nb((long)n * k);
    std::vector<double> nc((long)n * k);
    std::vector<int> idx(n);
    for (int i = 0; i < n; ++i) {
        std::iota(idx.begin(), idx.end(), 0);
        const double* row = cost.data() + (long)i * n;
        std::nth_element(idx.begin(), idx.begin() + k - 1, idx.end(),
                         [&](int a, int b) { return row[a] < row[b]; });
        for (int t = 0; t < k; ++t) {
            nb[(long)i * k + t] = idx[t];
            nc[(long)i * k + t] = row[idx[t]];
        }
    }
    std::vector<double> u(n), v(n);
    for (int i = 0; i < n; ++i) { u[i] = ud(rng) * 0.1; v[i] = ud(rng) * 0.1; }
    std::vector<int> row_of_col(n);
    std::iota(row_of_col.begin(), row_of_col.end(), 0);
    for (int j = 0; j < 40; ++j) row_of_col[j] = -1;
    Graph g{n, k, nb.data(), nc.data()};

    int reps = 600; // one full pass of n augmentations
    auto bench = [&](int threads) {
        auto t0 = std::chrono::high_resolution_clock::now();
        long sink = 0;
        if (threads == 1) {
            for (int r = 0; r < reps; ++r)
                sink += search(g, u.data(), v.data(), row_of_col.data(), r % n, limit);
        } else {
            std::vector<long> local(threads, 0);
            int chunk = (reps + threads - 1) / threads;
            std::vector<std::thread> ts;
            for (int t = 0; t < threads; ++t) {
                int lo = t * chunk, hi = std::min(reps, lo + chunk);
                ts.emplace_back([&, t, lo, hi]() {
                    long s = 0;
                    for (int r = lo; r < hi; ++r)
                        s += search(g, u.data(), v.data(), row_of_col.data(), r % n, limit);
                    local[t] = s;
                });
            }
            for (auto& th : ts) th.join();
            for (long s : local) sink += s;
        }
        auto t1 = std::chrono::high_resolution_clock::now();
        double ms = std::chrono::duration<double, std::milli>(t1 - t0).count();
        printf("threads=%d reps=%d total=%.2f ms per=%.4f ms sink=%ld\n",
               threads, reps, ms, ms / reps, sink);
    };
    for (int th : {1, 2, 4, 6, 8}) bench(th);
}
