#include <algorithm>
#include <chrono>
#include <cmath>
#include <cstdint>
#include <cstdio>
#include <numeric>
#include <queue>
#include <random>
#include <vector>

// Cost-scaling via Hopcroft-Karp on the equality graph of a k-NN instance,
// but here we just time HK itself on a random k-regular bipartite graph
// to see if matching is the cheap part.

int hopcroft(int n, int k, const int* nb, int* match_col) {
    // match_col[i] = column, match_row[j] = row
    std::vector<int> match_row(n, -1);
    std::fill(match_col, match_col + n, -1);
    std::vector<int> dist(n);
    int matching = 0;
    auto bfs = [&]() {
        std::queue<int> q;
        for (int i = 0; i < n; ++i) {
            if (match_col[i] < 0) { dist[i] = 0; q.push(i); }
            else dist[i] = -1;
        }
        bool found = false;
        while (!q.empty()) {
            int i = q.front(); q.pop();
            const int* cols = nb + (long)i * k;
            for (int t = 0; t < k; ++t) {
                int j = cols[t];
                int r = match_row[j];
                if (r < 0) found = true;
                else if (dist[r] < 0) { dist[r] = dist[i] + 1; q.push(r); }
            }
        }
        return found;
    };
    std::vector<int> ptr(n);
    auto dfs = [&](auto& self, int i) -> bool {
        const int* cols = nb + (long)i * k;
        for (int& t = ptr[i]; t < k; ++t) {
            int j = cols[t];
            int r = match_row[j];
            if (r < 0 || (dist[r] == dist[i] + 1 && self(self, r))) {
                match_row[j] = i;
                match_col[i] = j;
                return true;
            }
        }
        dist[i] = -1;
        return false;
    };
    while (bfs()) {
        std::fill(ptr.begin(), ptr.end(), 0);
        for (int i = 0; i < n; ++i)
            if (match_col[i] < 0 && dfs(dfs, i)) ++matching;
    }
    return matching;
}

int main() {
    int n = 600, k = 32;
    std::mt19937 rng(0);
    std::vector<int> nb((long)n * k);
    for (int i = 0; i < n; ++i) {
        // random neighbors
        std::vector<int> idx(n);
        std::iota(idx.begin(), idx.end(), 0);
        std::shuffle(idx.begin(), idx.end(), rng);
        for (int t = 0; t < k; ++t) nb[(long)i * k + t] = idx[t];
    }
    std::vector<int> match(n);
    auto t0 = std::chrono::high_resolution_clock::now();
    int m = 0;
    for (int rep = 0; rep < 20; ++rep) m = hopcroft(n, k, nb.data(), match.data());
    auto t1 = std::chrono::high_resolution_clock::now();
    double ms = std::chrono::duration<double, std::milli>(t1 - t0).count() / 20;
    printf("HK n=%d k=%d matching=%d time=%.3f ms\n", n, k, m, ms);
}
