{"command":"cat > ./build/scale.cpp << 'EOF'
#include <algorithm>
#include <chrono>
#include <cmath>
#include <cstdint>
#include <cstdio>
#include <numeric>
#include <queue>
#include <random>
#include <vector>

// Cost-scaling assignment on a complete bipartite graph, but equality edges are
// generated on the fly by scanning. This will be slow if we scan fully each phase.
// Instead: kNN graph only, integer costs, cost scaling + HK.
// Measure number of scaling phases and total HK time until the kNN-optimal matching
// (not necessarily global).

int hopcroft(int n, const std::vector<std::vector<int>>& adj, int* match_col, int* match_row) {
    std::fill(match_col, match_col + n, -1);
    std::fill(match_row, match_row + n, -1);
    std::vector<int> dist(n);
    int matching = 0;
    auto bfs = [&]() {
        std::queue<int> q;
        for (int i = 0; i < n; ++i) {
            if (match_col[i] < 0) { dist[i] = 0; q.push(i); }
            else dist[i] = -1;
        }
        bool found = false;
        while (!q.empty()) {
            int i = q.front(); q.pop();
            for (int j : adj[i]) {
                int r = match_row[j];
                if (r < 0) found = true;
                else if (dist[r] < 0) { dist[r] = dist[i] + 1; q.push(r); }
            }
        }
        return found;
    };
    std::vector<int> ptr(n);
    auto dfs = [&](auto& self, int i) -> bool {
        for (int& t = ptr[i]; t < (int)adj[i].size(); ++t) {
            int j = adj[i][t];
            int r = match_row[j];
            if (r < 0 || (dist[r] == dist[i] + 1 && self(self, r))) {
                match_row[j] = i;
                match_col[i] = j;
                return true;
            }
        }
        dist[i] = -1;
        return false;
    };
    while (bfs()) {
        std::fill(ptr.begin(), ptr.end(), 0);
        for (int i = 0; i < n; ++i)
            if (match_col[i] < 0 && dfs(dfs, i)) ++matching;
    }
    return matching;
}

int main() {
    int n = 600, k = 40, seed = 0;
    const int SCALE = 1000000; // costs in [0, SCALE]
    std::mt19937 rng(seed);
    std::uniform_real_distribution<double> ud(0, 1);
    std::vector<double> sp(n * 2), tp(n * 2);
    for (int i = 0; i < n * 2; ++i) { sp[i] = ud(rng); tp[i] = ud(rng); }
    std::vector<int> nb((long)n * k);
    std::vector<int> nc((long)n * k); // integer costs
    std::vector<int> idx(n);
    std::vector<double> rowd(n);
    int cmax = 0;
    for (int i = 0; i < n; ++i) {
        double sx = sp[2 * i], sy = sp[2 * i + 1];
        for (int j = 0; j < n; ++j) {
            double dx = sx - tp[2 * j], dy = sy - tp[2 * j + 1];
            rowd[j] = std::sqrt(dx * dx + dy * dy);
        }
        std::iota(idx.begin(), idx.end(), 0);
        std::nth_element(idx.begin(), idx.begin() + k - 1, idx.end(),
                         [&](int a, int b) { return rowd[a] < rowd[b]; });
        for (int t = 0; t < k; ++t) {
            nb[(long)i * k + t] = idx[t];
            int c = (int)std::llround(rowd[idx[t]] * SCALE);
            nc[(long)i * k + t] = c;
            if (c > cmax) cmax = c;
        }
    }

    // duals as integers. Cost scaling: threshold eps halves.
    std::vector<long long> u(n, 0), v(n, 0);
    // init u[i] = min neighbor cost
    for (int i = 0; i < n; ++i) {
        long long m = nc[(long)i * k];
        for (int t = 1; t < k; ++t) m = std::min(m, (long long)nc[(long)i * k + t]);
        u[i] = m;
    }
    std::vector<int> match_col(n), match_row(n);
    std::vector<std::vector<int>> adj(n);

    auto t0 = std::chrono::high_resolution_clock::now();
    int phases = 0;
    long long eps = 1;
    while ((eps << 1) <= cmax) eps <<= 1;
    // Gabow-Tarjan / cost-scaling skeleton:
    // while eps >= 1:
    //   build equality graph of edges with reduced cost < eps? 
    //   The standard scaling maintains  eps-optimality: reduced cost >= -eps.
    //   This implementation is a simplified "threshold auction-like" refine:
    //   repeatedly match in the graph of edges with reduced cost <= 0, then
    //   if not perfect, raise duals of free rows by eps. This is the Hungarian
    //   scaling variant and may not be the fastest, but let's count phases.
    int total_matching = 0;
    while (eps >= 1) {
        // refine until perfect matching in admissible graph (rc <= 0), raising free-component duals
        int guard = 0;
        while (guard++ < n) {
            for (int i = 0; i < n; ++i) adj[i].clear();
            for (int i = 0; i < n; ++i) {
                for (int t = 0; t < k; ++t) {
                    int j = nb[(long)i * k + t];
                    long long rc = nc[(long)i * k + t] - u[i] - v[j];
                    if (rc <= 0) adj[i].push_back(j);
                }
            }
            int m = hopcroft(n, adj, match_col.data(), match_row.data());
            ++phases;
            if (m == n) break;
            // dual update: free rows (unmatched) and columns reachable... simplified:
            // increase u of unmatched rows by eps, decrease? This naive update may not converge.
            // Proper: BFS from free rows in admissible graph, raise u of visited rows, lower v of visited cols.
            std::vector<char> visR(n, 0), visC(n, 0);
            std::queue<int> q;
            for (int i = 0; i < n; ++i) if (match_col[i] < 0) { visR[i] = 1; q.push(i); }
            while (!q.empty()) {
                int i = q.front(); q.pop();
                for (int j : adj[i]) if (!visC[j]) {
                    visC[j] = 1;
                    int r = match_row[j];
                    if (r >= 0 && !visR[r]) { visR[r] = 1; q.push(r); }
                }
            }
            for (int i = 0; i < n; ++i) if (visR[i]) u[i] += eps;
            for (int j = 0; j < n; ++j) if (visC[j]) v[j] -= eps;
        }
        eps >>= 1;
        ++total_matching;
    }
    auto t1 = std::chrono::high_resolution_clock::now();
    double ms = std::chrono::duration<double, std::milli>(t1 - t0).count();
    int bad = 0; std::vector<char> used(n, 0);
    long long sc = 0;
    for (int i = 0; i < n; ++i) {
        int j = match_col[i];
        if (j < 0 || used[j]) bad++;
        else {
            used[j] = 1;
            for (int t = 0; t < k; ++t) if (nb[(long)i * k + t] == j) { sc += nc[(long)i * k + t]; break; }
        }
    }
    printf("phases=%d outer=%d time=%.2f ms bad=%d cost_int=%lld\n", phases, total_matching, ms, bad, sc);
}
EOF
